"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import {
  axisParams,
  type ChartLegend,
  type ChartReference,
  type ChartRow,
  type ChartSeriesInput,
  categoryAxis,
  legendOption,
  legendRoom,
  numberAt,
  referenceLine,
  resolveSeries,
  seriesEntries,
  tableOf,
  tooltipBase,
  tooltipHtml,
  valueAxis,
} from "./option-parts"
import { specChart } from "./spec-chart"
import { type ChartTokens, type ChartTone, colorOf, withAlpha } from "./tokens"

export interface BandChartBand {
  /** The fields holding the range's floor and ceiling. */
  low: string
  high: string
  /** A field holding the central path, drawn dashed, such as a forecast. */
  mid?: string
  label?: string
  midLabel?: string
  /** The first series' color by default. */
  color?: ChartTone | string
}

export interface BandChartMarker {
  /** The `xKey` value the rule stands on. */
  x: string
  label?: string
}

export interface BandChartSpec {
  data: ChartRow[]
  xKey: string
  /** Solid lines, such as actuals. Every numeric field outside the band otherwise. */
  series?: ChartSeriesInput[]
  band: BandChartBand
  format?: ChartFormat
  /** Vertical rules, such as today or a launch. */
  markers?: BandChartMarker[]
  reference?: ChartReference
  legend?: ChartLegend
}

const lineSeries = (spec: BandChartSpec): ChartSeriesInput[] => {
  const { band } = spec
  const reserved = new Set([band.low, band.high, band.mid])
  return (
    spec.series ??
    seriesEntries(spec.data, spec.xKey, undefined)
      .filter((entry) => !reserved.has(entry.key))
      .map((entry) => entry.key)
  )
}

export const bandChartOption = (
  spec: BandChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const { data, xKey, band, markers = [] } = spec
  const format = toFormatter(spec.format)
  const lines = resolveSeries(tokens, data, xKey, lineSeries(spec))
  const labels = data.map((row) => String(row[xKey] ?? ""))
  const tone = band.color
    ? colorOf(tokens, band.color)
    : (lines[0]?.color ?? tokens.accent)
  const rangeName = band.label ?? "Range"
  const midName = band.midLabel ?? "Projected"
  const names = [
    ...lines.map((entry) => entry.label),
    ...(band.mid ? [midName] : []),
    rangeName,
  ]
  const legend = legendOption(tokens, spec.legend, names.length)
  const room = legendRoom(legend)
  const low = data.map((row) => numberAt(row, band.low))
  const high = data.map((row) => numberAt(row, band.high))
  const quiet = {
    type: "line" as const,
    showSymbol: false,
    // Stacks a positive span on a negative floor too, which "samesign" would refuse.
    stackStrategy: "all" as const,
  }

  return {
    grid: {
      left: 4,
      right: 16,
      top: room.top + (markers.length ? 16 : 0),
      bottom: room.bottom,
      containLabel: true,
    },
    legend: { ...legend, data: names },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "axis",
      axisPointer: { type: "line", lineStyle: { color: tokens.border, width: 1 } },
      formatter: (params: unknown) => {
        const at = axisParams(params)[0]?.dataIndex ?? -1
        const row = data[at]
        if (!row) return ""
        const floor = low[at]
        const ceiling = high[at]
        const mid = band.mid ? numberAt(row, band.mid) : null
        return tooltipHtml(labels[at] ?? "", [
          ...lines.flatMap((entry) => {
            const value = numberAt(row, entry.key)
            return value === null
              ? []
              : [{ name: entry.label, color: entry.color, value: format(value) }]
          }),
          ...(mid === null ? [] : [{ name: midName, color: tone, value: format(mid) }]),
          ...(floor == null || ceiling == null
            ? []
            : [
                {
                  name: rangeName,
                  color: withAlpha(tone, 0.4),
                  value: `${format(floor)} to ${format(ceiling)}`,
                },
              ]),
        ])
      },
    },
    xAxis: { ...categoryAxis(tokens, labels), boundaryGap: false },
    yAxis: valueAxis(tokens, format, width),
    series: [
      {
        ...quiet,
        name: "",
        stack: "band",
        silent: true,
        lineStyle: { opacity: 0 },
        tooltip: { show: false },
        data: low,
      },
      {
        ...quiet,
        name: rangeName,
        color: withAlpha(tone, 0.4),
        stack: "band",
        silent: true,
        lineStyle: { opacity: 0 },
        areaStyle: { color: withAlpha(tone, 0.16), opacity: 1 },
        data: high.map((value, index) => {
          const floor = low[index]
          return value === null || floor == null ? null : value - floor
        }),
      },
      ...(band.mid
        ? [
            {
              ...quiet,
              name: midName,
              color: tone,
              lineStyle: { color: tone, width: 2, type: "dashed" as const },
              data: data.map((row) => numberAt(row, band.mid ?? "")),
            },
          ]
        : []),
      ...lines.map((entry, index) => ({
        type: "line" as const,
        name: entry.label,
        color: entry.color,
        showSymbol: false,
        symbol: "circle",
        symbolSize: 6,
        lineStyle: {
          color: entry.color,
          width: 2,
          type: entry.dashed ? ("dashed" as const) : ("solid" as const),
        },
        emphasis: { focus: "series" as const },
        data: data.map((row) => numberAt(row, entry.key)),
        ...(index === 0 ? referenceLine(tokens, spec.reference, "yAxis") : {}),
        ...(index === 0 && markers.length
          ? {
              markLine: {
                silent: true,
                symbol: "none",
                lineStyle: { color: tokens.fgFaint, type: "solid" as const, width: 1 },
                label: {
                  position: "end",
                  color: tokens.fgMuted,
                  fontFamily: tokens.font,
                  fontSize: 11,
                  formatter: (params: { name: string }) => params.name,
                },
                data: [
                  ...markers.map((marker) => ({
                    xAxis: marker.x,
                    name: marker.label ?? "",
                  })),
                  ...(spec.reference
                    ? [
                        {
                          yAxis: spec.reference.value,
                          name: spec.reference.label ?? "",
                        },
                      ]
                    : []),
                ],
              },
            }
          : {}),
      })),
    ],
  } as EChartsOption
}

export interface BandChartProps extends ChartCommonProps, BandChartSpec {}

/** Lines inside a shaded range: a confidence band, or a forecast cone ahead of actuals. */
export const BandChart = specChart<BandChartSpec>({
  name: "BandChart",
  keys: ["data", "xKey", "series", "band", "format", "markers", "reference", "legend"],
  option: bandChartOption,
  table: (spec) =>
    tableOf(
      spec.data,
      spec.xKey,
      [
        ...seriesEntries(spec.data, spec.xKey, lineSeries(spec)),
        ...(spec.band.mid
          ? [{ key: spec.band.mid, label: spec.band.midLabel ?? "Projected" }]
          : []),
        { key: spec.band.low, label: `${spec.band.label ?? "Range"} low` },
        { key: spec.band.high, label: `${spec.band.label ?? "Range"} high` },
      ],
      toFormatter(spec.format),
    ),
  isEmpty: (spec) => spec.data.length === 0,
  label: "Band chart",
  height: 320,
})

"use client"

import { forwardRef, useCallback, useMemo } from "react"
import { Chart, type ChartCommonProps, useStableSpec } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import {
  axisParams,
  barFill,
  type ChartDatum,
  type ChartLegend,
  type ChartReference,
  type ChartRow,
  type ChartSeriesInput,
  categoryAxis,
  datumTable,
  legendOption,
  legendRoom,
  numberAt,
  referenceLine,
  resolveSeries,
  seriesEntries,
  sortData,
  tableOf,
  tooltipBase,
  tooltipHtml,
  valueAxis,
} from "./option-parts"
import { type ChartTokens, type ChartTone, colorOf, withAlpha } from "./tokens"

export type BarChartOrientation = "vertical" | "horizontal"
export type BarChartSort = "desc" | "asc" | "none"

const CAP = [6, 6, 2, 2]
const CAP_SIDEWAYS = [2, 6, 6, 2]
const ROW = 30

const valueLabel = (tokens: ChartTokens) => ({
  color: tokens.fgMuted,
  fontFamily: tokens.fontMono,
  fontSize: 11,
  distance: 6,
})

const shadowPointer = (tokens: ChartTokens) => ({
  type: "shadow" as const,
  shadowStyle: { color: withAlpha(tokens.fgFaint, 0.08) },
})

export interface BarChartSpec {
  data: ChartRow[]
  xKey: string
  series?: ChartSeriesInput[]
  format?: ChartFormat
  orientation?: BarChartOrientation
  /** Stacks the series in one bar; grouped side by side otherwise. */
  stacked?: boolean
  /** Prints each value at the end of its bar. */
  values?: boolean
  legend?: ChartLegend
  reference?: ChartReference
}

export const barChartOption = (
  {
    data,
    xKey,
    orientation = "vertical",
    stacked = false,
    values = false,
    ...spec
  }: BarChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const series = resolveSeries(tokens, data, xKey, spec.series)
  const labels = data.map((row) => String(row[xKey] ?? ""))
  const sideways = orientation === "horizontal"
  const legend = legendOption(tokens, spec.legend, series.length)
  const room = legendRoom(legend)
  const category = {
    ...categoryAxis(tokens, labels),
    ...(sideways ? { inverse: true } : {}),
  }
  const value = valueAxis(tokens, format, width)
  const totals = data.map((row) =>
    series.reduce((sum, entry) => sum + (numberAt(row, entry.key) ?? 0), 0),
  )

  return {
    grid: {
      left: 4,
      right: values && sideways ? 48 : 16,
      top: room.top + (values && !sideways ? 8 : 0),
      bottom: room.bottom,
      containLabel: true,
    },
    legend: { ...legend, data: series.map((entry) => entry.label) },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "axis",
      axisPointer: shadowPointer(tokens),
      formatter: (params: unknown) => {
        const hits = axisParams(params)
        const at = hits[0]?.dataIndex ?? -1
        const row = data[at]
        if (!row) return ""
        return tooltipHtml(
          labels[at] ?? "",
          hits.flatMap((hit) => {
            const entry = series[hit.seriesIndex]
            if (!entry) return []
            const amount = numberAt(row, entry.key)
            return [
              {
                name: entry.label,
                color: entry.color,
                value: amount === null ? "n/a" : format(amount),
              },
            ]
          }),
        )
      },
    },
    xAxis: sideways ? value : category,
    yAxis: sideways ? category : value,
    series: series.map((entry, index) => ({
      type: "bar",
      name: entry.label,
      color: entry.color,
      stack: stacked ? "total" : undefined,
      data: data.map((row) => numberAt(row, entry.key)),
      barMaxWidth: series.length > 2 && !stacked ? 18 : 28,
      barGap: "18%",
      barCategoryGap: "34%",
      itemStyle: {
        color: barFill(entry.color, sideways),
        borderRadius: stacked ? 2 : sideways ? CAP_SIDEWAYS : CAP,
      },
      label: {
        show: values && (!stacked || index === series.length - 1),
        position: sideways ? "right" : "top",
        ...valueLabel(tokens),
        formatter: (params: { value: number; dataIndex: number }) =>
          format(stacked ? (totals[params.dataIndex] ?? 0) : params.value),
      },
      emphasis: { focus: "series" },
      blur: { itemStyle: { opacity: 0.35 } },
      ...(index === 0
        ? referenceLine(tokens, spec.reference, sideways ? "xAxis" : "yAxis")
        : {}),
    })),
  } as EChartsOption
}

export interface RankedBarsSpec {
  data: ChartDatum[]
  format?: ChartFormat
  /** Rows shown, largest first. */
  limit?: number
  sort?: BarChartSort
  /** Prints each value at the end of its bar. */
  values?: boolean
  color?: ChartTone | string
  reference?: ChartReference
}

export const rankedBarsOption = (
  {
    data,
    limit = 10,
    sort = "desc",
    values = true,
    color,
    reference,
    ...spec
  }: RankedBarsSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const rows = sortData(data, sort).slice(0, limit)
  const fallback = colorOf(tokens, color)

  return {
    grid: {
      left: 4,
      right: values ? 56 : 16,
      top: reference?.label ? 24 : 8,
      bottom: 4,
      containLabel: true,
    },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const at = axisParams(params)[0]?.dataIndex ?? -1
        const row = rows[at]
        return row
          ? tooltipHtml(row.label, [{ name: "Value", value: format(row.value) }])
          : ""
      },
    },
    xAxis: valueAxis(tokens, format, width),
    yAxis: {
      ...categoryAxis(
        tokens,
        rows.map((row) => row.label),
      ),
      inverse: true,
      axisLine: { show: false },
      axisLabel: {
        ...categoryAxis(tokens, []).axisLabel,
        interval: 0,
        width: 140,
        overflow: "truncate",
      },
    },
    series: [
      {
        type: "bar",
        name: "Value",
        color: fallback,
        data: rows.map((row) => ({
          value: row.value,
          itemStyle: {
            color: barFill(row.color ? colorOf(tokens, row.color) : fallback, true),
            borderRadius: CAP_SIDEWAYS,
          },
        })),
        barMaxWidth: 16,
        animationDelay: (index: number) => index * 28,
        label: {
          show: values,
          position: "right",
          ...valueLabel(tokens),
          formatter: (params: { value: number }) => format(params.value),
        },
        emphasis: { focus: "self" },
        blur: { itemStyle: { opacity: 0.35 } },
        ...referenceLine(tokens, reference, "xAxis"),
      },
    ],
  } as EChartsOption
}

export interface DivergingBarsSpec {
  /** Signed values: above zero runs right, below runs left. */
  data: ChartDatum[]
  format?: ChartFormat
  sort?: BarChartSort
  /** For measures where a fall is good, such as cost or churn. */
  invert?: boolean
  values?: boolean
  /** What the left end of the axis means, such as “Losing share”. */
  negativeLabel?: string
  positiveLabel?: string
}

export const divergingBarsOption = (
  {
    data,
    sort = "desc",
    invert = false,
    values = true,
    negativeLabel,
    positiveLabel,
    ...spec
  }: DivergingBarsSpec,
  tokens: ChartTokens,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const signed = (value: number) => `${value > 0 ? "+" : ""}${format(value)}`
  const rows = sortData(data, sort)
  // Symmetric around zero, with room past the widest bar for its label.
  const widest = Math.max(...rows.map((row) => Math.abs(row.value)))
  const reach = (widest > 0 ? widest : 1) * (values ? 1.3 : 1.05)
  const poles = Boolean(negativeLabel || positiveLabel)
  const tone = (value: number) =>
    value >= 0 !== invert ? tokens.success : tokens.danger
  const pole = (text: string | undefined, side: "left" | "right") =>
    text
      ? [
          {
            type: "text",
            top: 0,
            [side]: 4,
            silent: true,
            style: {
              text: side === "left" ? `← ${text}` : `${text} →`,
              fill: tokens.fgFaint,
              font: `11px ${tokens.font}`,
            },
          },
        ]
      : []

  return {
    grid: { left: 4, right: 4, top: poles ? 28 : 8, bottom: 4, containLabel: true },
    graphic: [...pole(negativeLabel, "left"), ...pole(positiveLabel, "right")],
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const at = axisParams(params)[0]?.dataIndex ?? -1
        const row = rows[at]
        return row
          ? tooltipHtml(row.label, [
              { name: "Change", color: tone(row.value), value: signed(row.value) },
            ])
          : ""
      },
    },
    xAxis: {
      type: "value",
      min: -reach,
      max: reach,
      axisLine: { show: false },
      axisTick: { show: false },
      axisLabel: { show: false },
      splitLine: { show: false },
    },
    yAxis: {
      ...categoryAxis(
        tokens,
        rows.map((row) => row.label),
      ),
      inverse: true,
      axisLine: { show: false },
      axisLabel: {
        ...categoryAxis(tokens, []).axisLabel,
        interval: 0,
        width: 140,
        overflow: "truncate",
      },
    },
    series: [
      {
        type: "bar",
        name: "Change",
        data: rows.map((row) => {
          const color = row.color ? colorOf(tokens, row.color) : tone(row.value)
          return {
            value: row.value,
            itemStyle: {
              color: barFill(color, row.value >= 0),
              borderRadius: row.value >= 0 ? CAP_SIDEWAYS : [6, 2, 2, 6],
            },
            label: {
              show: values,
              position: row.value >= 0 ? "right" : "left",
              ...valueLabel(tokens),
              formatter: () => signed(row.value),
            },
          }
        }),
        barMaxWidth: 14,
        emphasis: { focus: "self" },
        blur: { itemStyle: { opacity: 0.35 } },
        markLine: {
          silent: true,
          symbol: "none",
          animation: false,
          label: { show: false },
          lineStyle: { color: tokens.border, type: "solid", width: 1 },
          data: [{ xAxis: 0 }],
        },
      },
    ],
  } as EChartsOption
}

export interface BarChartProps extends ChartCommonProps, BarChartSpec {}
export interface RankedBarsProps extends ChartCommonProps, RankedBarsSpec {}
export interface DivergingBarsProps extends ChartCommonProps, DivergingBarsSpec {}

/** Columns or rows per category, grouped or stacked. */
export const BarChart = forwardRef<HTMLDivElement, BarChartProps>(
  (
    {
      data,
      xKey,
      series,
      format,
      orientation,
      stacked,
      values,
      legend,
      reference,
      label = "Bar chart",
      summary = true,
      empty = "No data to plot",
      ...props
    },
    ref,
  ) => {
    const spec = useStableSpec(
      { data, xKey, series, format, orientation, stacked, values, legend, reference },
      format,
    )
    const option = useCallback(
      (tokens: ChartTokens, width: number) => barChartOption(spec, tokens, width),
      [spec],
    )
    const table = useMemo(
      () =>
        summary
          ? tableOf(
              spec.data,
              spec.xKey,
              seriesEntries(spec.data, spec.xKey, spec.series),
              toFormatter(spec.format),
            )
          : undefined,
      [summary, spec],
    )
    return (
      <Chart
        ref={ref}
        option={option}
        label={label}
        summary={table}
        empty={data.length === 0 ? empty : undefined}
        {...props}
      />
    )
  },
)

BarChart.displayName = "BarChart"

/** Which is biggest: sorted rows with values printed, against an optional reference. */
export const RankedBars = forwardRef<HTMLDivElement, RankedBarsProps>(
  (
    {
      data,
      format,
      limit = 10,
      sort,
      values,
      color,
      reference,
      height,
      label = "Ranked bars",
      summary = true,
      empty = "No data to plot",
      ...props
    },
    ref,
  ) => {
    const spec = useStableSpec(
      { data, format, limit, sort, values, color, reference },
      format,
    )
    const option = useCallback(
      (tokens: ChartTokens, width: number) => rankedBarsOption(spec, tokens, width),
      [spec],
    )
    const table = useMemo(
      () =>
        summary
          ? datumTable(
              sortData(spec.data, spec.sort ?? "desc").slice(0, limit),
              toFormatter(spec.format),
            )
          : undefined,
      [summary, spec, limit],
    )
    const rows = Math.min(data.length, limit)
    return (
      <Chart
        ref={ref}
        option={option}
        label={label}
        height={height ?? Math.max(rows * ROW + 48, 160)}
        summary={table}
        empty={data.length === 0 ? empty : undefined}
        {...props}
      />
    )
  },
)

RankedBars.displayName = "RankedBars"

/** How far each row sits above or below zero, toned by whether that is good. */
export const DivergingBars = forwardRef<HTMLDivElement, DivergingBarsProps>(
  (
    {
      data,
      format,
      sort,
      invert,
      values,
      negativeLabel,
      positiveLabel,
      height,
      label = "Diverging bars",
      summary = true,
      empty = "No data to plot",
      ...props
    },
    ref,
  ) => {
    const spec = useStableSpec(
      { data, format, sort, invert, values, negativeLabel, positiveLabel },
      format,
    )
    const option = useCallback(
      (tokens: ChartTokens) => divergingBarsOption(spec, tokens),
      [spec],
    )
    const table = useMemo(
      () =>
        summary
          ? datumTable(
              sortData(spec.data, spec.sort ?? "desc"),
              toFormatter(spec.format),
            )
          : undefined,
      [summary, spec],
    )
    const poles = negativeLabel || positiveLabel ? 24 : 0
    return (
      <Chart
        ref={ref}
        option={option}
        label={label}
        height={height ?? Math.max(data.length * ROW + 24 + poles, 140)}
        summary={table}
        empty={data.length === 0 ? empty : undefined}
        {...props}
      />
    )
  },
)

DivergingBars.displayName = "DivergingBars"

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import { categoryAxis, tooltipBase, tooltipHtml, valueAxis } from "./option-parts"
import { specChart } from "./spec-chart"
import { type ChartTokens, type ChartTone, colorOf, withAlpha } from "./tokens"

export interface BoxplotChartGroup {
  label: string
  /** Raw observations; the five-number summary is computed from them. */
  values: number[]
  color?: ChartTone | string
}

export interface BoxplotChartSpec {
  data: BoxplotChartGroup[]
  format?: ChartFormat
  orientation?: "vertical" | "horizontal"
  /** Draws points past the whiskers. On by default. */
  outliers?: boolean
}

export interface BoxplotChartStats {
  min: number
  q1: number
  median: number
  q3: number
  max: number
  /** Observations beyond 1.5 × IQR from the box. */
  outliers: number[]
}

const quantile = (sorted: readonly number[], p: number): number => {
  if (sorted.length === 0) return 0
  const at = (sorted.length - 1) * p
  const low = Math.floor(at)
  const high = Math.ceil(at)
  const a = sorted[low] ?? 0
  const b = sorted[high] ?? a
  return a + (b - a) * (at - low)
}

/** Tukey's box: quartiles by linear interpolation, whiskers at the last point within 1.5 × IQR. */
export const boxplotStats = (values: readonly number[]): BoxplotChartStats => {
  const sorted = values.filter(Number.isFinite).sort((a, b) => a - b)
  const q1 = quantile(sorted, 0.25)
  const q3 = quantile(sorted, 0.75)
  const reach = (q3 - q1) * 1.5
  const inside = sorted.filter((value) => value >= q1 - reach && value <= q3 + reach)
  return {
    min: inside[0] ?? 0,
    q1,
    median: quantile(sorted, 0.5),
    q3,
    max: inside[inside.length - 1] ?? 0,
    outliers: sorted.filter((value) => value < q1 - reach || value > q3 + reach),
  }
}

export const boxplotChartOption = (
  { data, orientation = "vertical", outliers = true, ...spec }: BoxplotChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const stats = data.map((group) => boxplotStats(group.values))
  const sideways = orientation === "horizontal"
  const category = {
    ...categoryAxis(
      tokens,
      data.map((group) => group.label),
    ),
    ...(sideways ? { inverse: true, axisLine: { show: false } } : {}),
  }
  const value = valueAxis(tokens, format, width)

  return {
    grid: { left: 4, right: 16, top: 16, bottom: 4, containLabel: true },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const hit = params as { dataIndex: number; seriesType: string; value: number[] }
        const group = data[hit.dataIndex]
        const box = stats[hit.dataIndex]
        if (hit.seriesType === "scatter") {
          const point = hit.value[sideways ? 0 : 1] ?? 0
          const owner = data[hit.value[sideways ? 1 : 0] ?? -1]
          return tooltipHtml(owner?.label ?? "", [
            { name: "Outlier", color: tokens.danger, value: format(point) },
          ])
        }
        if (!group || !box) return ""
        return tooltipHtml(group.label, [
          { name: "Max", value: format(box.max) },
          { name: "Q3", value: format(box.q3) },
          { name: "Median", value: format(box.median) },
          { name: "Q1", value: format(box.q1) },
          { name: "Min", value: format(box.min) },
          { name: "Count", value: String(group.values.length) },
        ])
      },
    },
    xAxis: sideways ? value : category,
    yAxis: sideways ? category : value,
    series: [
      {
        type: "boxplot",
        name: "Distribution",
        layout: sideways ? "horizontal" : "vertical",
        boxWidth: [8, 36],
        data: stats.map((box, index) => {
          const color = colorOf(tokens, data[index]?.color, 0)
          return {
            value: [box.min, box.q1, box.median, box.q3, box.max],
            itemStyle: {
              color: withAlpha(color, 0.2),
              borderColor: color,
              borderWidth: 1.5,
            },
          }
        }),
        emphasis: { itemStyle: { borderWidth: 2 } },
      },
      ...(outliers
        ? [
            {
              type: "scatter",
              name: "Outliers",
              symbolSize: 6,
              itemStyle: {
                color: tokens.surface,
                borderColor: tokens.fgMuted,
                borderWidth: 1.5,
              },
              data: stats.flatMap((box, index) =>
                box.outliers.map((point) => (sideways ? [point, index] : [index, point])),
              ),
            },
          ]
        : []),
    ],
  } as EChartsOption
}

export interface BoxplotChartProps extends ChartCommonProps, BoxplotChartSpec {}

/** Spread, centre and outliers of each group at a glance, from raw observations. */
export const BoxplotChart = specChart<BoxplotChartSpec>({
  name: "BoxplotChart",
  keys: ["data", "format", "orientation", "outliers"],
  option: boxplotChartOption,
  table: (spec) => {
    const print = toFormatter(spec.format)
    return {
      columns: ["Group", "Min", "Q1", "Median", "Q3", "Max", "Outliers"],
      rows: spec.data.map((group) => {
        const box = boxplotStats(group.values)
        return [
          group.label,
          print(box.min),
          print(box.q1),
          print(box.median),
          print(box.q3),
          print(box.max),
          box.outliers.length,
        ]
      }),
    }
  },
  isEmpty: (spec) => spec.data.every((group) => group.values.length === 0),
  label: "Box plot",
  height: 320,
})

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, formatPercent, toFormatter } from "./format"
import {
  axisParams,
  categoryAxis,
  tooltipBase,
  tooltipHtml,
  valueAxis,
} from "./option-parts"
import { type CustomApi, type CustomParams, specChart } from "./spec-chart"
import { type ChartTokens, type ChartTone, colorOf, withAlpha } from "./tokens"

export interface BulletChartRow {
  label: string
  value: number
  target?: number
  /** Upper bounds of the qualitative ranges, such as poor, fair and good, ascending. */
  bands?: number[]
}

export interface BulletChartSpec {
  data: BulletChartRow[]
  format?: ChartFormat
  /** The shared scale's end. The largest value, target or band otherwise. */
  max?: number
  color?: ChartTone | string
}

const ROW = 44

const ceilingOf = ({ data, max }: BulletChartSpec) =>
  max ??
  Math.max(
    ...data.flatMap((row) => [row.value, row.target ?? 0, ...(row.bands ?? [])]),
    Number.EPSILON,
  ) * 1.04

export const bulletChartOption = (
  spec: BulletChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const { data } = spec
  const format = toFormatter(spec.format)
  const fill = colorOf(tokens, spec.color)
  const ceiling = ceilingOf(spec)

  return {
    grid: { left: 4, right: 20, top: 8, bottom: 4, containLabel: true },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "axis",
      axisPointer: { type: "none" },
      formatter: (params: unknown) => {
        const row = data[axisParams(params)[0]?.dataIndex ?? -1]
        if (!row) return ""
        return tooltipHtml(row.label, [
          { name: "Value", color: fill, value: format(row.value) },
          ...(row.target === undefined
            ? []
            : [
                { name: "Target", color: tokens.fg, value: format(row.target) },
                {
                  name: "Of target",
                  value: formatPercent(row.target ? row.value / row.target : 0),
                },
              ]),
        ])
      },
    },
    xAxis: { ...valueAxis(tokens, format, width), min: 0, max: ceiling },
    yAxis: {
      ...categoryAxis(
        tokens,
        data.map((row) => row.label),
      ),
      inverse: true,
      axisLine: { show: false },
      axisLabel: {
        ...categoryAxis(tokens, []).axisLabel,
        interval: 0,
        width: 140,
        overflow: "truncate",
      },
    },
    series: [
      {
        type: "custom",
        name: "Value",
        encode: { x: 1, y: 0 },
        data: data.map((row, index) => [index, row.value]),
        renderItem: (params: CustomParams, api: CustomApi) => {
          const index = params.dataIndex
          const row = data[index]
          if (!row) return null
          const slot = api.size([0, 1])[1] ?? ROW
          const [zero = 0, middle = 0] = api.coord([0, index])
          const at = (value: number) =>
            api.coord([Math.min(value, ceiling), index])[0] ?? 0
          const track = Math.min(slot * 0.62, 26)
          const bar = track * 0.38
          // Widest band first, so each narrower and darker band paints over it.
          const bands = [...(row.bands?.length ? row.bands : [ceiling])].sort(
            (a, b) => b - a,
          )
          return {
            type: "group",
            children: [
              ...bands.map((bound, step) => ({
                type: "rect",
                silent: true,
                shape: {
                  x: zero,
                  y: middle - track / 2,
                  width: Math.max(at(bound) - zero, 0),
                  height: track,
                  r: 3,
                },
                style: { fill: withAlpha(tokens.fgFaint, 0.1 + step * 0.08) },
              })),
              {
                type: "rect",
                shape: {
                  x: zero,
                  y: middle - bar / 2,
                  width: Math.max(at(row.value) - zero, 0),
                  height: bar,
                  r: 2,
                },
                style: { fill },
              },
              ...(row.target === undefined
                ? []
                : [
                    {
                      type: "rect",
                      silent: true,
                      shape: {
                        x: at(row.target) - 1.5,
                        y: middle - track * 0.42,
                        width: 3,
                        height: track * 0.84,
                        r: 1,
                      },
                      style: { fill: tokens.fg },
                    },
                  ]),
            ],
          }
        },
      },
    ],
  } as EChartsOption
}

export interface BulletChartProps extends ChartCommonProps, BulletChartSpec {}

/** A value against its target and qualitative ranges, compact enough to stack many. */
export const BulletChart = specChart<BulletChartSpec>({
  name: "BulletChart",
  keys: ["data", "format", "max", "color"],
  option: bulletChartOption,
  table: (spec) => {
    const print = toFormatter(spec.format)
    return {
      columns: ["Measure", "Value", "Target", "Ranges"],
      rows: spec.data.map((row) => [
        row.label,
        print(row.value),
        row.target === undefined ? null : print(row.target),
        row.bands?.map(print).join(", ") ?? null,
      ]),
    }
  },
  isEmpty: (spec) => spec.data.length === 0,
  label: "Bullet chart",
  height: (spec) => Math.max(spec.data.length * ROW + 36, 120),
})

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, formatPercent, toFormatter } from "./format"
import {
  axisParams,
  categoryAxis,
  tooltipBase,
  tooltipHtml,
  valueAxis,
} from "./option-parts"
import { specChart } from "./spec-chart"
import { type ChartTokens, withAlpha } from "./tokens"

export interface CandlestickChartCandle {
  label: string
  open: number
  close: number
  low: number
  high: number
}

export interface CandlestickChartSpec {
  data: CandlestickChartCandle[]
  format?: ChartFormat
  /** A moving average of closes over this many candles, drawn as a thin line. */
  average?: number
}

export const movingAverage = (
  values: readonly number[],
  span: number,
): (number | null)[] =>
  values.map((_, index) => {
    if (span < 1 || index < span - 1) return null
    let sum = 0
    for (let at = index - span + 1; at <= index; at++) sum += values[at] ?? 0
    return sum / span
  })

export const candlestickChartOption = (
  { data, average, ...spec }: CandlestickChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const closes = data.map((candle) => candle.close)
  const trend = average ? movingAverage(closes, average) : []

  return {
    grid: { left: 4, right: 12, top: 16, bottom: 4, containLabel: true },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "axis",
      axisPointer: { type: "line", lineStyle: { color: tokens.border } },
      formatter: (params: unknown) => {
        const candle = data[axisParams(params)[0]?.dataIndex ?? -1]
        if (!candle) return ""
        const up = candle.close >= candle.open
        const move = candle.open === 0 ? 0 : (candle.close - candle.open) / candle.open
        return tooltipHtml(candle.label, [
          { name: "Open", value: format(candle.open) },
          { name: "High", value: format(candle.high) },
          { name: "Low", value: format(candle.low) },
          {
            name: "Close",
            color: up ? tokens.success : tokens.danger,
            value: `${format(candle.close)} (${move > 0 ? "+" : ""}${formatPercent(move)})`,
          },
        ])
      },
    },
    xAxis: {
      ...categoryAxis(
        tokens,
        data.map((candle) => candle.label),
      ),
      boundaryGap: true,
    },
    yAxis: { ...valueAxis(tokens, format, width), scale: true },
    series: [
      {
        type: "candlestick",
        name: "Price",
        barMaxWidth: 14,
        data: data.map((candle) => [candle.open, candle.close, candle.low, candle.high]),
        // Up candles are hollow, so direction never rests on color alone.
        itemStyle: {
          color: withAlpha(tokens.success, 0.18),
          color0: tokens.danger,
          borderColor: tokens.success,
          borderColor0: tokens.danger,
          borderWidth: 1.5,
        },
        emphasis: { itemStyle: { borderWidth: 2 } },
      },
      ...(average
        ? [
            {
              type: "line",
              name: `${average}-period average`,
              data: trend,
              symbol: "none",
              smooth: true,
              lineStyle: { color: tokens.accent, width: 1.5 },
              z: 3,
            },
          ]
        : []),
    ],
  } as EChartsOption
}

export interface CandlestickChartProps extends ChartCommonProps, CandlestickChartSpec {}

/** Open, high, low and close per period: hollow bodies rise, filled bodies fall. */
export const CandlestickChart = specChart<CandlestickChartSpec>({
  name: "CandlestickChart",
  keys: ["data", "format", "average"],
  option: candlestickChartOption,
  table: (spec) => {
    const print = toFormatter(spec.format)
    return {
      columns: ["Period", "Open", "High", "Low", "Close"],
      rows: spec.data.map((candle) => [
        candle.label,
        print(candle.open),
        print(candle.high),
        print(candle.low),
        print(candle.close),
      ]),
    }
  },
  isEmpty: (spec) => spec.data.length === 0,
  label: "Candlestick chart",
  height: 320,
})

"use client"

import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react"
import { useReducedMotion } from "../lib/hooks/use-reduced-motion"
import { useComposedRefs } from "../lib/utils/compose-refs"
import { cx } from "../lib/utils/cx"
import { type EChartsOption, type EChartsType, init } from "./echarts"
import { themeOption } from "./option-parts"
import { type ChartTokens, readChartTokens, tokenSignature } from "./tokens"

export type ChartOptionBuilder = (tokens: ChartTokens, width: number) => EChartsOption

export interface ChartSummary {
  caption?: string
  columns: string[]
  rows: (string | number | null)[][]
}

export interface ChartProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  /** A raw ECharts option, or a builder that receives the live theme and the plot width. */
  option: EChartsOption | ChartOptionBuilder
  /** Names the chart for assistive tech. */
  label: string
  /** Number in px or any CSS length. */
  height?: number | string
  /** A visually hidden table of the plotted data, announced with the chart. */
  summary?: ChartSummary
  /** Rendered instead of the canvas, for a chart with nothing to plot. */
  empty?: ReactNode
  /** Called with the ECharts instance once it exists. Return a cleanup to unbind events. */
  onInit?: (instance: EChartsType) => void | (() => void)
}

/** Props every data-first chart shares. */
export interface ChartCommonProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "children" | "color"
> {
  /** Names the chart for assistive tech. */
  label?: string
  height?: number | string
  /** Adds a visually hidden table of the data. On by default. */
  summary?: boolean
  /** Shown instead of the chart when there is no data. */
  empty?: ReactNode
}

/**
 * Keeps a spec referentially stable while its serializable content and functions are
 * unchanged, so inline `data={[...]}` does not replay the chart on every parent render.
 */
export const useStableSpec = <T extends object>(spec: T, ...functions: unknown[]): T =>
  useMemo(() => spec, [JSON.stringify(spec), ...functions])

// Width is quantised so dragging a window edge rebuilds the option on real resizes only.
const STEP = 8
const WATCHED = ["class", "style", "data-theme", "data-kg-scope"]
const SUMMARY_ROWS = 60

const Summary = ({ id, summary }: { id: string; summary: ChartSummary }) => (
  <table id={id} className="kg-visually-hidden">
    {summary.caption ? <caption>{summary.caption}</caption> : null}
    <thead>
      <tr>
        {summary.columns.map((column, index) => (
          <th key={index} scope="col">
            {column}
          </th>
        ))}
      </tr>
    </thead>
    <tbody>
      {summary.rows.slice(0, SUMMARY_ROWS).map((row, index) => (
        <tr key={index}>
          {row.map((cell, column) => (
            <td key={column}>{cell ?? "n/a"}</td>
          ))}
        </tr>
      ))}
    </tbody>
  </table>
)

/**
 * The ECharts host: one canvas per chart, themed from the `--kg-*` properties in scope and
 * rebuilt when the theme, accent or size changes. Renders an empty box on the server.
 */
export const Chart = forwardRef<HTMLDivElement, ChartProps>(
  (
    { option, label, height = 280, summary, empty, onInit, className, style, ...props },
    ref,
  ) => {
    const root = useRef<HTMLDivElement>(null)
    const plot = useRef<HTMLDivElement>(null)
    const chart = useRef<EChartsType | null>(null)
    const composed = useComposedRefs(root, ref)
    const summaryId = useId()
    const reduced = useReducedMotion()
    const [tokens, setTokens] = useState<ChartTokens | null>(null)
    const [width, setWidth] = useState(0)
    const isEmpty = empty != null

    useEffect(() => {
      const scope = root.current
      const node = plot.current
      if (!scope || !node || isEmpty) return

      const instance = init(node, undefined, { renderer: "canvas" })
      chart.current = instance

      const measure = () => setWidth(Math.round(node.clientWidth / STEP) * STEP)
      // A resize can be queued before cleanup and delivered after it.
      const resizer = new ResizeObserver(() => {
        if (instance.isDisposed()) return
        instance.resize()
        measure()
      })
      resizer.observe(node)
      measure()

      // Canvas holds resolved colors, so a theme, accent or scope change must re-read them.
      // Only a real color change commits, or every unrelated style write would replay the chart.
      let signature = ""
      const read = () => {
        const next = readChartTokens(scope)
        const nextSignature = tokenSignature(next)
        if (nextSignature === signature) return
        signature = nextSignature
        setTokens(next)
      }
      read()
      const watcher = new MutationObserver(read)
      const watch = { attributes: true, attributeFilter: WATCHED }
      watcher.observe(document.documentElement, watch)
      const themed = scope.parentElement?.closest<HTMLElement>(
        "[data-theme], [data-kg-scope]",
      )
      if (themed && themed !== document.documentElement) watcher.observe(themed, watch)
      const dark = window.matchMedia("(prefers-color-scheme: dark)")
      dark.addEventListener("change", read)

      return () => {
        resizer.disconnect()
        watcher.disconnect()
        dark.removeEventListener("change", read)
        instance.dispose()
        chart.current = null
      }
    }, [isEmpty])

    useEffect(() => {
      const instance = chart.current
      if (!instance || !onInit) return
      const detach = onInit(instance)
      return () => {
        if (!instance.isDisposed()) detach?.()
      }
    }, [onInit, isEmpty])

    const resolved = useMemo(() => {
      if (!tokens || width === 0) return null
      return themeOption(
        typeof option === "function" ? option(tokens, width) : option,
        tokens,
      )
    }, [option, tokens, width])

    useEffect(() => {
      const instance = chart.current
      if (!instance || instance.isDisposed() || !resolved) return
      instance.setOption(reduced ? { ...resolved, animation: false } : resolved, {
        notMerge: true,
      })
    }, [resolved, reduced])

    const box = {
      ...style,
      "--_height": typeof height === "number" ? `${height}px` : height,
    } as CSSProperties

    return (
      <div
        ref={composed}
        className={cx("kg-chart", className)}
        style={box}
        data-empty={isEmpty || undefined}
        {...props}
      >
        {isEmpty ? (
          // Keyed apart from the plot: dispose() wipes the innerHTML of the node ECharts owns.
          <div key="empty" className="kg-chart__empty" role="note" aria-label={label}>
            {empty}
          </div>
        ) : (
          <div
            key="plot"
            ref={plot}
            className="kg-chart__plot"
            role="img"
            aria-label={label}
            aria-busy={resolved ? undefined : true}
            data-state={resolved ? "ready" : "loading"}
            aria-describedby={summary ? summaryId : undefined}
          />
        )}
        {summary && !isEmpty ? <Summary id={summaryId} summary={summary} /> : null}
      </div>
    )
  },
)

Chart.displayName = "Chart"

@layer kg.components {
  /* Palette tints lean toward the light end in both themes, so they never sink into a dark canvas. */
  :root,
  [data-theme="light"],
  .light {
    --_kg-chart-tint: var(--kg-bg);
    --_kg-chart-quiet: 28%;
  }

  [data-theme="dark"],
  .dark {
    --_kg-chart-tint: var(--kg-fg);
    --_kg-chart-quiet: 44%;
  }

  @media (prefers-color-scheme: dark) {
    [data-theme="system"] {
      --_kg-chart-tint: var(--kg-fg);
      --_kg-chart-quiet: 44%;
    }
  }

  .kg-chart {
    position: relative;
    min-width: 0;
  }

  .kg-chart__plot[data-state="loading"] {
    background:
      linear-gradient(
          100deg,
          transparent 30%,
          color-mix(in oklab, var(--kg-fg) 5%, transparent) 50%,
          transparent 70%
        )
        0 0 / 250% 100%,
      var(--kg-surface-sunken);
    border-radius: var(--kg-radius-lg);
    animation: kg-chart-shimmer 1.6s linear infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    .kg-chart__plot[data-state="loading"] {
      animation-duration: 4s;
    }
  }

  [data-kg-motion="reduce"] .kg-chart__plot[data-state="loading"] {
    animation-duration: 4s;
  }

  @keyframes kg-chart-shimmer {
    from {
      background-position: 100% 0;
    }
    to {
      background-position: -150% 0;
    }
  }

  .kg-chart__plot,
  .kg-chart__empty {
    width: 100%;
    height: var(--_height, 280px);
  }

  .kg-chart__empty {
    display: grid;
    place-items: center;
    padding: calc(var(--kg-space) * 4);
    font-size: var(--kg-text-sm);
    color: var(--kg-fg-muted);
    text-align: center;
    border: 1px dashed var(--kg-border);
    border-radius: var(--kg-radius-lg);
  }

  /* ECharts writes inline styles on the tooltip shell, hence !important on what it sets. */
  .kg-chart-tooltip {
    min-width: 8.5rem;
    max-width: 18rem;
    padding: calc(var(--kg-space) * 2.5) calc(var(--kg-space) * 3) !important;
    font-size: var(--kg-text-sm) !important;
    line-height: 1.45 !important;
    font-variant-numeric: tabular-nums;
    color: var(--kg-fg) !important;
    background: var(--kg-surface-raised) !important;
    border: 1px solid var(--kg-border) !important;
    border-radius: var(--kg-radius-lg) !important;
    box-shadow:
      var(--kg-shadow-inset-edge),
      0 0 0 0.5px oklch(var(--kg-shadow-tint) / 0.04),
      var(--kg-shadow-lg) !important;
    /* Fades only: ECharts would otherwise glide the box across the plot from its last spot. */
    transition: opacity var(--kg-duration-fast) var(--kg-ease-out) !important;

    &:empty {
      display: none !important;
    }
  }

  .kg-chart-tooltip__title {
    margin-block-end: calc(var(--kg-space) * 1.5);
    padding-block-end: calc(var(--kg-space) * 1.5);
    font-weight: 600;
    color: var(--kg-fg);
    border-block-end: 1px solid var(--kg-border);
  }

  .kg-chart-tooltip__row {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    column-gap: calc(var(--kg-space) * 2);

    & + & {
      margin-block-start: calc(var(--kg-space) * 1);
    }
  }

  .kg-chart-tooltip__swatch {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: var(--kg-radius-full);
  }

  .kg-chart-tooltip__name {
    grid-column: 2;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--kg-fg-muted);
  }

  .kg-chart-tooltip__value {
    grid-column: 3;
    font-family: var(--kg-font-mono);
    font-size: var(--kg-text-xs);
    font-weight: 600;
    color: var(--kg-fg);
  }

  .kg-spark-grid {
    --_tile: 180px;

    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(var(--_tile), 100%), 1fr));
    gap: calc(var(--kg-space) * 3);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .kg-spark-grid__tile {
    min-width: 0;
    padding: calc(var(--kg-space) * 4);
    background: var(--kg-surface);
    border: 1px solid var(--kg-border);
    border-radius: var(--kg-radius-lg);
    box-shadow: var(--kg-shadow-inset-edge), var(--kg-shadow-xs);
  }
}

"use client"

import { forwardRef, useCallback, useMemo } from "react"
import { Chart, type ChartCommonProps, useStableSpec } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import type { LineChartCurve } from "./line-chart"
import {
  axisParams,
  barFill,
  type ChartLegend,
  type ChartRow,
  type ChartSeriesInput,
  categoryAxis,
  lastPointMark,
  legendOption,
  legendRoom,
  numberAt,
  resolveSeries,
  seriesEntries,
  tableOf,
  tooltipBase,
  tooltipHtml,
  valueAxis,
} from "./option-parts"
import { type ChartTokens, withAlpha } from "./tokens"

export interface ComboChartSpec {
  data: ChartRow[]
  xKey: string
  /** Fields drawn as columns, on the left axis. */
  bars: ChartSeriesInput[]
  /** Fields drawn as lines, on the right axis when `dualAxis` is on. */
  lines: ChartSeriesInput[]
  /** Formats the bars and the left axis. */
  format?: ChartFormat
  /** Formats the lines and the right axis. Defaults to `format`. */
  lineFormat?: ChartFormat
  dualAxis?: boolean
  stacked?: boolean
  curve?: LineChartCurve
  legend?: ChartLegend
}

export const comboChartOption = (
  {
    data,
    xKey,
    dualAxis = true,
    stacked = false,
    curve = "smooth",
    ...spec
  }: ComboChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const lineFormat =
    spec.lineFormat === undefined ? format : toFormatter(spec.lineFormat)
  const bars = resolveSeries(tokens, data, xKey, spec.bars)
  const lines = resolveSeries(tokens, data, xKey, spec.lines, bars.length)
  const all = [...bars, ...lines]
  const labels = data.map((row) => String(row[xKey] ?? ""))
  const legend = legendOption(tokens, spec.legend, all.length)
  const room = legendRoom(legend)
  const right = dualAxis && lines.length > 0

  return {
    grid: {
      left: 4,
      right: right ? 4 : 16,
      top: room.top,
      bottom: room.bottom,
      containLabel: true,
    },
    legend: { ...legend, data: all.map((entry) => entry.label) },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "axis",
      axisPointer: {
        type: "shadow",
        shadowStyle: { color: withAlpha(tokens.fgFaint, 0.08) },
      },
      formatter: (params: unknown) => {
        const hits = axisParams(params)
        const at = hits[0]?.dataIndex ?? -1
        const row = data[at]
        if (!row) return ""
        return tooltipHtml(
          labels[at] ?? "",
          hits.flatMap((hit) => {
            const entry = all[hit.seriesIndex]
            if (!entry) return []
            const value = numberAt(row, entry.key)
            const print = hit.seriesIndex < bars.length ? format : lineFormat
            return [
              {
                name: entry.label,
                color: entry.color,
                value: value === null ? "n/a" : print(value),
              },
            ]
          }),
        )
      },
    },
    xAxis: categoryAxis(tokens, labels),
    yAxis: [
      valueAxis(tokens, format, width),
      ...(right
        ? [{ ...valueAxis(tokens, lineFormat, width), splitLine: { show: false } }]
        : []),
    ],
    series: [
      ...bars.map((entry) => ({
        type: "bar",
        name: entry.label,
        color: entry.color,
        stack: stacked ? "bars" : undefined,
        data: data.map((row) => numberAt(row, entry.key)),
        barMaxWidth: 24,
        barGap: "18%",
        itemStyle: {
          color: barFill(entry.color),
          borderRadius: stacked ? 2 : [6, 6, 2, 2],
        },
        emphasis: { focus: "series" },
        blur: { itemStyle: { opacity: 0.35 } },
      })),
      ...lines.map((entry) => {
        const values = data.map((row) => numberAt(row, entry.key))
        return {
          type: "line",
          name: entry.label,
          color: entry.color,
          yAxisIndex: right ? 1 : 0,
          data: values,
          smooth: curve === "smooth" ? 0.35 : false,
          smoothMonotone: "x",
          step: curve === "step" ? "middle" : false,
          showSymbol: false,
          symbol: "circle",
          symbolSize: 6,
          z: 3,
          lineStyle: {
            width: 2,
            color: entry.color,
            type: entry.dashed ? "dashed" : "solid",
            cap: "round",
            join: "round",
          },
          itemStyle: {
            color: entry.color,
            borderColor: tokens.surface,
            borderWidth: 1.5,
          },
          emphasis: { focus: "series" },
          ...lastPointMark(tokens, entry.color, values),
        }
      }),
    ],
  } as EChartsOption
}

export interface ComboChartProps extends ChartCommonProps, ComboChartSpec {}

/** Columns for one measure, lines for another, each on its own axis. */
export const ComboChart = forwardRef<HTMLDivElement, ComboChartProps>(
  (
    {
      data,
      xKey,
      bars,
      lines,
      format,
      lineFormat,
      dualAxis,
      stacked,
      curve,
      legend,
      label = "Combo chart",
      summary = true,
      empty = "No data to plot",
      ...props
    },
    ref,
  ) => {
    const spec = useStableSpec(
      { data, xKey, bars, lines, format, lineFormat, dualAxis, stacked, curve, legend },
      format,
      lineFormat,
    )
    const option = useCallback(
      (tokens: ChartTokens, width: number) => comboChartOption(spec, tokens, width),
      [spec],
    )
    const table = useMemo(() => {
      if (!summary) return undefined
      const barEntries = seriesEntries(spec.data, spec.xKey, spec.bars)
      const lineEntries = seriesEntries(spec.data, spec.xKey, spec.lines)
      const barTable = tableOf(
        spec.data,
        spec.xKey,
        barEntries,
        toFormatter(spec.format),
      )
      const lineTable = tableOf(
        spec.data,
        spec.xKey,
        lineEntries,
        toFormatter(spec.lineFormat ?? spec.format),
      )
      return {
        columns: [...barTable.columns, ...lineTable.columns.slice(1)],
        rows: barTable.rows.map((row, index) => [
          ...row,
          ...(lineTable.rows[index] ?? []).slice(1),
        ]),
      }
    }, [summary, spec])
    return (
      <Chart
        ref={ref}
        option={option}
        label={label}
        summary={table}
        empty={data.length === 0 ? empty : undefined}
        {...props}
      />
    )
  },
)

ComboChart.displayName = "ComboChart"

"use client"

import { forwardRef, useCallback, useMemo } from "react"
import { Chart, type ChartCommonProps, useStableSpec } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, formatPercent, toFormatter } from "./format"
import {
  type ChartDatum,
  type ChartLegend,
  datumTable,
  legendOption,
  tooltipBase,
  tooltipHtml,
} from "./option-parts"
import { type ChartTokens, colorOf } from "./tokens"

export type DonutChartVariant = "donut" | "pie"

export interface DonutChartSpec {
  data: ChartDatum[]
  format?: ChartFormat
  variant?: DonutChartVariant
  /** Printed in the hole under the value. */
  centerLabel?: string
  /** Replaces the total printed in the hole. */
  centerValue?: string
  /** Names and shares outside the ring. */
  labels?: boolean
  legend?: ChartLegend
}

export const donutChartOption = (
  {
    data,
    variant = "donut",
    centerLabel,
    centerValue,
    labels = true,
    ...spec
  }: DonutChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const total = data.reduce((sum, datum) => sum + datum.value, 0)
  const donut = variant === "donut"
  const legend = legendOption(tokens, spec.legend ?? false, data.length)
  const below = legend.show && legend.bottom !== undefined
  // On a phone the outside labels need the ring smaller, or they clip at the edge.
  const outer = labels ? (width > 0 && width < 420 ? "56%" : "70%") : "86%"
  const center = ["50%", legend.show ? (below ? "45%" : "55%") : "50%"]

  return {
    legend: { ...legend, data: data.map((datum) => datum.label) },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const slice = params as {
          name: string
          value: number
          percent: number
          color: string
        }
        return tooltipHtml(slice.name, [
          { name: "Value", color: slice.color, value: format(slice.value) },
          { name: "Share", value: formatPercent(slice.percent / 100) },
        ])
      },
    },
    series: [
      {
        type: "pie",
        radius: [donut ? "58%" : "0%", outer],
        center,
        startAngle: 90,
        minAngle: 2,
        avoidLabelOverlap: true,
        animationType: "expansion",
        padAngle: donut ? 1.2 : 0,
        itemStyle: {
          borderColor: tokens.surface,
          borderWidth: donut ? 0 : 2,
          borderRadius: donut ? 4 : 2,
        },
        label: {
          show: labels,
          formatter: (params: { name: string; percent: number }) =>
            `{name|${params.name}}\n{value|${formatPercent(params.percent / 100)}}`,
          lineHeight: 15,
          rich: {
            name: { color: tokens.fgMuted, fontFamily: tokens.font, fontSize: 11 },
            value: {
              color: tokens.fg,
              fontFamily: tokens.fontMono,
              fontSize: 11,
              fontWeight: 600,
            },
          },
        },
        labelLine: {
          show: labels,
          length: 8,
          length2: 10,
          lineStyle: { color: tokens.border },
        },
        emphasis: { scale: true, scaleSize: 5, focus: "self" },
        blur: { itemStyle: { opacity: 0.35 } },
        data: data.map((datum, index) => ({
          name: datum.label,
          value: datum.value,
          itemStyle: { color: colorOf(tokens, datum.color, index) },
        })),
      },
    ],
    graphic: donut
      ? [
          {
            type: "text",
            left: "center",
            top: center[1] === "50%" ? "middle" : center[1] === "55%" ? "52%" : "42%",
            silent: true,
            style: {
              text: centerLabel
                ? `{value|${centerValue ?? format(total)}}\n{label|${centerLabel}}`
                : `{value|${centerValue ?? format(total)}}`,
              align: "center",
              rich: {
                value: {
                  fill: tokens.fg,
                  fontFamily: tokens.font,
                  fontSize: 20,
                  fontWeight: 650,
                  lineHeight: 26,
                  align: "center",
                },
                label: {
                  fill: tokens.fgMuted,
                  fontFamily: tokens.font,
                  fontSize: 11,
                  lineHeight: 16,
                  align: "center",
                },
              },
            },
          },
        ]
      : [],
  } as EChartsOption
}

export interface DonutChartProps extends ChartCommonProps, DonutChartSpec {}

/** Share of a whole, with the total in the hole. */
export const DonutChart = forwardRef<HTMLDivElement, DonutChartProps>(
  (
    {
      data,
      format,
      variant,
      centerLabel,
      centerValue,
      labels,
      legend,
      label = "Donut chart",
      summary = true,
      empty = "No data to plot",
      ...props
    },
    ref,
  ) => {
    const spec = useStableSpec(
      { data, format, variant, centerLabel, centerValue, labels, legend },
      format,
    )
    const option = useCallback(
      (tokens: ChartTokens, width: number) => donutChartOption(spec, tokens, width),
      [spec],
    )
    const table = useMemo(
      () => (summary ? datumTable(spec.data, toFormatter(spec.format)) : undefined),
      [summary, spec],
    )
    return (
      <Chart
        ref={ref}
        option={option}
        label={label}
        summary={table}
        empty={data.length === 0 ? empty : undefined}
        {...props}
      />
    )
  },
)

DonutChart.displayName = "DonutChart"

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, formatPercent, toFormatter } from "./format"
import {
  axisParams,
  categoryAxis,
  legendOption,
  tooltipBase,
  tooltipHtml,
  valueAxis,
} from "./option-parts"
import { type CustomApi, type CustomParams, specChart } from "./spec-chart"
import { type ChartTokens, withAlpha } from "./tokens"

export interface DumbbellChartRow {
  label: string
  /** The earlier value: a hollow dot. */
  from: number | null
  /** The later value: a solid accent dot. */
  to: number | null
}

export interface DumbbellChartSpec {
  data: DumbbellChartRow[]
  fromLabel?: string
  toLabel?: string
  format?: ChartFormat
  /** For measures where a fall is good, such as cost or churn. */
  invert?: boolean
  /** Orders rows by their later value. */
  sort?: "desc" | "asc" | "none"
}

const ROW = 34

const sorted = (rows: readonly DumbbellChartRow[], sort: DumbbellChartSpec["sort"]) =>
  sort === "desc" || sort === "asc"
    ? [...rows].sort((a, b) =>
        sort === "desc" ? (b.to ?? 0) - (a.to ?? 0) : (a.to ?? 0) - (b.to ?? 0),
      )
    : [...rows]

const change = (row: DumbbellChartRow) =>
  row.from !== null && row.to !== null && row.from !== 0
    ? (row.to - row.from) / Math.abs(row.from)
    : null

export const dumbbellChartOption = (
  {
    data,
    fromLabel = "Before",
    toLabel = "After",
    invert = false,
    sort = "none",
    ...spec
  }: DumbbellChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const rows = sorted(data, sort)
  const legend = legendOption(tokens, "top", 2)
  const tone = (row: DumbbellChartRow) =>
    (row.to ?? 0) >= (row.from ?? 0) !== invert ? tokens.success : tokens.danger
  const dot = (key: "from" | "to") =>
    rows.map((row, index) => (row[key] === null ? null : [row[key], index]))

  return {
    legend: { ...legend, icon: "circle", data: [fromLabel, toLabel] },
    grid: { left: 4, right: 16, top: 36, bottom: 4, containLabel: true },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "axis",
      axisPointer: {
        type: "shadow",
        shadowStyle: { color: withAlpha(tokens.fgFaint, 0.08) },
      },
      formatter: (params: unknown) => {
        const row = rows[axisParams(params)[0]?.dataIndex ?? -1]
        if (!row) return ""
        const delta = change(row)
        return tooltipHtml(row.label, [
          {
            name: fromLabel,
            color: tokens.fgFaint,
            value: row.from === null ? "n/a" : format(row.from),
          },
          {
            name: toLabel,
            color: tokens.accent,
            value: row.to === null ? "n/a" : format(row.to),
          },
          ...(delta === null
            ? []
            : [
                {
                  name: "Change",
                  color: tone(row),
                  value: `${delta > 0 ? "+" : ""}${formatPercent(delta)}`,
                },
              ]),
        ])
      },
    },
    xAxis: { ...valueAxis(tokens, format, width), scale: true },
    yAxis: {
      ...categoryAxis(
        tokens,
        rows.map((row) => row.label),
      ),
      inverse: true,
      axisLine: { show: false },
      axisLabel: {
        ...categoryAxis(tokens, []).axisLabel,
        interval: 0,
        width: 140,
        overflow: "truncate",
      },
    },
    series: [
      {
        type: "custom",
        name: "Change",
        silent: true,
        encode: { x: [1, 2], y: 0 },
        data: rows.map((row, index) => [index, row.from ?? row.to, row.to ?? row.from]),
        renderItem: (params: CustomParams, api: CustomApi) => {
          const row = rows[params.dataIndex]
          if (!row || row.from === null || row.to === null) return null
          const [x1 = 0, y = 0] = api.coord([row.from, params.dataIndex])
          const [x2 = 0] = api.coord([row.to, params.dataIndex])
          return {
            type: "line",
            shape: { x1, y1: y, x2, y2: y },
            style: {
              stroke: withAlpha(tone(row), 0.55),
              lineWidth: 4,
              lineCap: "round",
            },
          }
        },
        tooltip: { show: false },
      },
      {
        type: "scatter",
        name: fromLabel,
        color: tokens.fgFaint,
        symbolSize: 11,
        itemStyle: {
          color: tokens.surface,
          borderColor: tokens.fgFaint,
          borderWidth: 2,
        },
        data: dot("from"),
        z: 3,
      },
      {
        type: "scatter",
        name: toLabel,
        color: tokens.accent,
        symbolSize: 12,
        itemStyle: {
          color: tokens.accent,
          borderColor: tokens.surface,
          borderWidth: 1.5,
        },
        data: dot("to"),
        z: 4,
      },
    ],
  } as EChartsOption
}

export interface DumbbellChartProps extends ChartCommonProps, DumbbellChartSpec {}

/** Each row's move between two periods on one scale: size and direction at once. */
export const DumbbellChart = specChart<DumbbellChartSpec>({
  name: "DumbbellChart",
  keys: ["data", "fromLabel", "toLabel", "format", "invert", "sort"],
  option: dumbbellChartOption,
  table: (spec) => {
    const print = toFormatter(spec.format)
    return {
      columns: ["Label", spec.fromLabel ?? "Before", spec.toLabel ?? "After", "Change"],
      rows: sorted(spec.data, spec.sort).map((row) => {
        const delta = change(row)
        return [
          row.label,
          row.from === null ? null : print(row.from),
          row.to === null ? null : print(row.to),
          delta === null ? null : `${delta > 0 ? "+" : ""}${formatPercent(delta)}`,
        ]
      }),
    }
  },
  isEmpty: (spec) => spec.data.length === 0,
  label: "Dumbbell chart",
  height: (spec) => Math.max(spec.data.length * ROW + 56, 160),
})

export type ChartFormatter = (value: number) => string

/**
 * How values print on axes, labels, tooltips and the data table. A preset or
 * `Intl.NumberFormatOptions` stays serializable; a function is the escape hatch.
 */
export type ChartFormat =
  | "number"
  | "compact"
  | "percent"
  | "currency"
  | Intl.NumberFormatOptions
  | ChartFormatter

// Fixed locale so the server-rendered data table matches the client's.
const LOCALE = "en-US"
const cache = new Map<string, Intl.NumberFormat>()

const formatter = (options: Intl.NumberFormatOptions): Intl.NumberFormat => {
  const key = JSON.stringify(options)
  let entry = cache.get(key)
  if (!entry) {
    entry = new Intl.NumberFormat(LOCALE, options)
    cache.set(key, entry)
  }
  return entry
}

export interface FormatCompactOptions {
  /** ISO code such as `"USD"`; prints a currency symbol. */
  currency?: string
  digits?: number
}

/** `1234567` → `1.2M`, `-48200` → `-48.2K`. */
export const formatCompact = (
  value: number,
  { currency, digits = 1 }: FormatCompactOptions = {},
): string =>
  formatter({
    notation: "compact",
    maximumFractionDigits: digits,
    ...(currency ? { style: "currency", currency } : {}),
  }).format(value)

/** A ratio printed as a percentage: `0.124` → `12.4%`. */
export const formatPercent = (value: number, digits = 1): string =>
  formatter({ style: "percent", maximumFractionDigits: digits }).format(value)

export const toFormatter = (format: ChartFormat = "compact"): ChartFormatter => {
  if (typeof format === "function") return format
  if (format === "compact") return (value) => formatCompact(value)
  if (format === "percent") return (value) => formatPercent(value)
  if (format === "currency") return (value) => formatCompact(value, { currency: "USD" })
  const intl = formatter(format === "number" ? { maximumFractionDigits: 2 } : format)
  return (value) => intl.format(value)
}

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, formatPercent, toFormatter } from "./format"
import { type ChartDatum, tooltipBase, tooltipHtml } from "./option-parts"
import { specChart } from "./spec-chart"
import { type ChartTokens, colorOf, withAlpha } from "./tokens"

export interface FunnelChartSpec {
  /** Stages in order, widest first. */
  data: ChartDatum[]
  format?: ChartFormat
  /** Prints each stage's share of the first one next to its value. */
  conversion?: boolean
}

export const funnelChartOption = (
  { data, conversion = true, ...spec }: FunnelChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const first = data[0]?.value ?? 0
  const share = (value: number) => (first > 0 ? value / first : 0)
  const narrow = width > 0 && width < 420

  return {
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const index = (params as { dataIndex: number }).dataIndex
        const stage = data[index]
        if (!stage) return ""
        const previous = data[index - 1]
        return tooltipHtml(stage.label, [
          { name: "Value", value: format(stage.value) },
          { name: "Of first stage", value: formatPercent(share(stage.value)) },
          ...(previous && previous.value > 0
            ? [
                {
                  name: "From previous",
                  value: formatPercent(stage.value / previous.value),
                },
              ]
            : []),
        ])
      },
    },
    series: [
      {
        type: "funnel",
        sort: "none",
        left: 4,
        top: 8,
        bottom: 8,
        width: narrow ? "52%" : "60%",
        minSize: "14%",
        gap: 3,
        funnelAlign: "center",
        itemStyle: { borderWidth: 0, borderRadius: 4 },
        emphasis: { label: { show: true } },
        // Outside, so every stage keeps the theme's ink whatever its fill.
        label: {
          show: true,
          position: "right",
          formatter: (params: { name: string; value: number }) =>
            `{name|${params.name}}\n{value|${format(params.value)}}` +
            (conversion ? `  {share|${formatPercent(share(params.value))}}` : ""),
          lineHeight: 16,
          rich: {
            name: { color: tokens.fgMuted, fontFamily: tokens.font, fontSize: 11 },
            value: {
              color: tokens.fg,
              fontFamily: tokens.fontMono,
              fontSize: 12,
              fontWeight: 600,
            },
            share: { color: tokens.fgFaint, fontFamily: tokens.fontMono, fontSize: 11 },
          },
        },
        labelLine: { length: 28, lineStyle: { color: tokens.border } },
        data: data.map((stage, index) => ({
          name: stage.label,
          value: stage.value,
          itemStyle: {
            color: stage.color
              ? colorOf(tokens, stage.color)
              : withAlpha(tokens.accent, Math.max(1 - index * 0.14, 0.32)),
          },
        })),
      },
    ],
  } as EChartsOption
}

export interface FunnelChartProps extends ChartCommonProps, FunnelChartSpec {}

/** How many make it through each stage, and what share of the start that is. */
export const FunnelChart = specChart<FunnelChartSpec>({
  name: "FunnelChart",
  keys: ["data", "format", "conversion"],
  option: funnelChartOption,
  table: ({ data, format }) => {
    const print = toFormatter(format)
    const first = data[0]?.value ?? 0
    return {
      columns: ["Stage", "Value", "Of first stage"],
      rows: data.map((stage) => [
        stage.label,
        print(stage.value),
        formatPercent(first > 0 ? stage.value / first : 0),
      ]),
    }
  },
  isEmpty: (spec) => spec.data.length === 0,
  label: "Funnel chart",
  height: 320,
})

"use client"

import { forwardRef, useCallback, useMemo } from "react"
import { Chart, type ChartCommonProps, useStableSpec } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import { type ChartTokens, type ChartTone, colorOf, withAlpha } from "./tokens"

export interface GaugeChartSpec {
  value: number
  min?: number
  max?: number
  format?: ChartFormat
  /** Printed under the value. */
  caption?: string
  /** A tick on the arc, such as a goal. */
  target?: number
  color?: ChartTone | string
}

const START = 225
const END = -45

export const gaugeChartOption = (
  { value, min = 0, max = 100, caption, target, color, ...spec }: GaugeChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format ?? "number")
  const fill = colorOf(tokens, color)
  const band = width > 0 && width < 260 ? 10 : 14
  const geometry = {
    type: "gauge",
    startAngle: START,
    endAngle: END,
    min,
    max,
    radius: "88%",
    center: ["50%", "54%"],
    splitNumber: 1,
    axisTick: { show: false },
    splitLine: { show: false },
    axisLabel: { show: false },
    anchor: { show: false },
  }

  return {
    series: [
      {
        ...geometry,
        progress: {
          show: true,
          roundCap: true,
          width: band,
          itemStyle: { color: fill },
        },
        axisLine: {
          roundCap: true,
          lineStyle: { width: band, color: [[1, withAlpha(tokens.fgFaint, 0.18)]] },
        },
        pointer: { show: false },
        title: {
          show: Boolean(caption),
          offsetCenter: [0, "30%"],
          color: tokens.fgMuted,
          fontFamily: tokens.font,
          fontSize: 12,
        },
        detail: {
          valueAnimation: true,
          offsetCenter: [0, caption ? "-2%" : "6%"],
          color: tokens.fg,
          fontFamily: tokens.font,
          fontSize: width > 0 && width < 260 ? 22 : 30,
          fontWeight: 650,
          formatter: (current: number) => format(current),
        },
        data: [{ value: Math.min(Math.max(value, min), max), name: caption ?? "" }],
      },
      ...(target === undefined
        ? []
        : [
            {
              ...geometry,
              silent: true,
              progress: { show: false },
              axisLine: { show: false },
              title: { show: false },
              detail: { show: false },
              pointer: {
                show: true,
                icon: "rect",
                width: 3,
                length: "22%",
                offsetCenter: [0, "-80%"],
                itemStyle: { color: tokens.fg },
              },
              data: [{ value: Math.min(Math.max(target, min), max) }],
            },
          ]),
    ],
  } as EChartsOption
}

export interface GaugeChartProps extends ChartCommonProps, GaugeChartSpec {}

/** One value against its range, with an optional target tick. */
export const GaugeChart = forwardRef<HTMLDivElement, GaugeChartProps>(
  (
    {
      value,
      min,
      max,
      format,
      caption,
      target,
      color,
      label,
      height = 220,
      summary = true,
      empty,
      ...props
    },
    ref,
  ) => {
    const spec = useStableSpec(
      { value, min, max, format, caption, target, color },
