          ["Range", `${print(spec.min ?? 0)} to ${print(spec.max ?? 100)}`],
          ...(spec.target === undefined ? [] : [["Target", print(spec.target)]]),
        ],
      }
    }, [summary, spec])
    return (
      <Chart
        ref={ref}
        option={option}
        label={label ?? caption ?? "Gauge"}
        height={height}
        summary={table}
        empty={empty}
        {...props}
