"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import { legendOption, tooltipBase, tooltipHtml } from "./option-parts"
import { specChart } from "./spec-chart"
import { type ChartTokens, withAlpha } from "./tokens"

export interface GraphChartNode {
  /** Unique, and what links refer to. */
  id: string
  label?: string
  /** Sizes the node. Its link count is used otherwise. */
  value?: number
  /** Nodes in one group share a color and a legend entry. */
  group?: string
}

export interface GraphChartLink {
  source: string
  target: string
  value?: number
}

export interface GraphChartSpec {
  nodes: GraphChartNode[]
  links: GraphChartLink[]
  format?: ChartFormat
  /** Names beside the larger nodes. On by default. */
  labels?: boolean
  /** Lets people drag nodes and pan the layout. */
  interactive?: boolean
}

/** Each node's number of links, the default measure of its weight. */
export const graphDegrees = (
  nodes: readonly GraphChartNode[],
  links: readonly GraphChartLink[],
): Map<string, number> => {
  const degrees = new Map(nodes.map((node) => [node.id, 0]))
  for (const link of links) {
    if (!degrees.has(link.source) || !degrees.has(link.target)) continue
    for (const end of [link.source, link.target]) degrees.set(end, (degrees.get(end) ?? 0) + 1)
  }
  return degrees
}

export const graphChartOption = (
  { nodes, links, labels = true, interactive = false, ...spec }: GraphChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const degrees = graphDegrees(nodes, links)
  const groups = [...new Set(nodes.map((node) => node.group ?? ""))].filter(Boolean)
  const weight = (node: GraphChartNode) => node.value ?? degrees.get(node.id) ?? 0
  const heaviest = Math.max(...nodes.map(weight), 1)
  const narrow = width > 0 && width < 520
  const legend = legendOption(tokens, groups.length > 1 ? "bottom" : false, groups.length)
  const known = new Set(nodes.map((node) => node.id))
  const strongest = Math.max(...links.map((link) => link.value ?? 1), 1)

  return {
    legend: { ...legend, icon: "circle", data: groups },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const hit = params as {
          dataType: "node" | "edge"
          name: string
          color: string
          data: { source?: string; target?: string; value?: number; group?: string }
        }
        if (hit.dataType === "edge")
          return tooltipHtml(`${hit.data.source ?? ""} to ${hit.data.target ?? ""}`, [
            ...(hit.data.value === undefined
              ? []
              : [{ name: "Weight", value: format(hit.data.value) }]),
          ])
        return tooltipHtml(hit.name, [
          ...(hit.data.group ? [{ name: "Group", color: hit.color, value: hit.data.group }] : []),
          { name: "Value", value: format(hit.data.value ?? 0) },
        ])
      },
    },
    series: [
      {
        type: "graph",
        layout: "force",
        roam: interactive,
        draggable: interactive,
        top: 12,
        bottom: groups.length > 1 ? 40 : 12,
        left: 12,
        right: 12,
        force: {
          repulsion: narrow ? 90 : 160,
          gravity: 0.08,
          edgeLength: narrow ? [30, 70] : [50, 110],
          friction: 0.2,
        },
        categories: groups.map((name) => ({ name })),
        emphasis: { focus: "adjacency", lineStyle: { width: 2 } },
        blur: { itemStyle: { opacity: 0.2 }, lineStyle: { opacity: 0.05 } },
        lineStyle: { color: withAlpha(tokens.fgFaint, 0.5), width: 1, curveness: 0.12 },
        itemStyle: { borderColor: tokens.surface, borderWidth: 1.5 },
        label: {
          show: labels,
          position: "right",
          color: tokens.fgMuted,
          fontFamily: tokens.font,
          fontSize: 11,
        },
        labelLayout: { hideOverlap: true },
        data: nodes.map((node) => {
          const share = weight(node) / heaviest
          return {
            id: node.id,
            name: node.label ?? node.id,
            value: weight(node),
            group: node.group,
            category: node.group ? groups.indexOf(node.group) : undefined,
            symbolSize: 8 + share * (narrow ? 18 : 26),
            // In a crowded graph small nodes stay unlabelled so the names that matter are readable.
            label: { show: labels && (nodes.length <= 12 || share >= 0.34) },
          }
        }),
        links: links
          .filter((link) => known.has(link.source) && known.has(link.target))
          .map((link) => ({
            source: link.source,
            target: link.target,
            value: link.value,
            lineStyle: link.value
              ? { width: 0.75 + (link.value / strongest) * 2.5 }
              : undefined,
          })),
      },
    ],
  } as EChartsOption
}

export interface GraphChartProps extends ChartCommonProps, GraphChartSpec {}

/** A network: who connects to whom, laid out by force so clusters pull together. */
export const GraphChart = specChart<GraphChartSpec>({
  name: "GraphChart",
  keys: ["nodes", "links", "format", "labels", "interactive"],
  option: graphChartOption,
  table: (spec) => {
    const print = toFormatter(spec.format)
    return {
      columns: ["From", "To", "Weight"],
      rows: spec.links.map((link) => [
        link.source,
        link.target,
        link.value === undefined ? null : print(link.value),
      ]),
    }
  },
  isEmpty: (spec) => spec.nodes.length === 0,
  label: "Network graph",
  height: 380,
})

"use client"

import type { ChartCommonProps, ChartSummary } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import { categoryAxis, tooltipBase, tooltipHtml } from "./option-parts"
import { inkOn, signedFormat, specChart } from "./spec-chart"
import { type ChartTokens, withAlpha } from "./tokens"

export interface HeatmapChartCell {
  x: string
  y: string
  value: number | null
}

export interface HeatmapChartDay {
  /** ISO date, `YYYY-MM-DD`. */
  date: string
  value: number | null
}

/** `sequential` runs from a faint wash to the accent; `diverging` from danger to success. */
export type HeatmapChartScheme = "sequential" | "diverging"

export interface HeatmapChartSpec {
  /** Category by category cells. */
  data?: HeatmapChartCell[]
  /** Calendar mode: one cell per day, laid out in weeks. Takes precedence over `data`. */
  days?: HeatmapChartDay[]
  /** Column and row order; first appearance in `data` otherwise. */
  xLabels?: string[]
  yLabels?: string[]
  format?: ChartFormat
  scheme?: HeatmapChartScheme
  /** Prints each cell's value. On by default for grids of 80 cells or fewer. */
  values?: boolean
  /** The color scale under the plot. */
  scale?: boolean
}

const unique = (values: readonly string[]) => [...new Set(values)]

const finite = (values: readonly (number | null)[]) =>
  values.filter((value): value is number => value !== null && Number.isFinite(value))

export const heatmapChartOption = (
  {
    data = [],
    days,
    scheme = "sequential",
    scale = true,
    values,
    ...spec
  }: HeatmapChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const print = scheme === "diverging" ? signedFormat(format) : format
  const calendar = days !== undefined
  const numbers = finite((days ?? data).map((entry) => entry.value))
  const low = numbers.length > 0 ? Math.min(...numbers) : 0
  const high = numbers.length > 0 ? Math.max(...numbers) : 1
  const reach = Math.max(Math.abs(low), Math.abs(high)) || 1
  const [min, max] =
    scheme === "diverging" ? [-reach, reach] : [low, high > low ? high : low + 1]
  const ramp =
    scheme === "diverging"
      ? [tokens.danger, withAlpha(tokens.fgFaint, 0.12), tokens.success]
      : [withAlpha(tokens.accent, 0.08), withAlpha(tokens.accent, 0.5), tokens.accent]

  const visualMap = {
    type: "continuous",
    show: scale,
    min,
    max,
    calculable: false,
    orient: "horizontal",
    left: "center",
    bottom: 0,
    itemWidth: 10,
    itemHeight: Math.min(160, Math.max(width * 0.3, 80)),
    inRange: { color: ramp },
    textGap: 6,
    textStyle: { color: tokens.fgFaint, fontFamily: tokens.fontMono, fontSize: 10 },
    text: [print(max), print(min)],
  }
  const cell = { borderColor: tokens.surface, borderWidth: 2, borderRadius: 4 }
  const bottom = scale ? 40 : 8

  if (calendar) {
    const dates = days.map((day) => day.date).sort()
    const first = dates[0] ?? ""
    const last = dates[dates.length - 1] ?? first
    return {
      visualMap,
      tooltip: {
        ...tooltipBase(tokens),
        trigger: "item",
        formatter: (params: unknown) => {
          const [date, value] = (params as { value: [string, number | null] }).value
          return tooltipHtml(date, [
            { name: "Value", value: value === null ? "n/a" : print(value) },
          ])
        },
      },
      calendar: {
        range: [first, last],
        top: 24,
        left: 36,
        right: 8,
        bottom,
        cellSize: ["auto", "auto"],
        splitLine: { show: false },
        itemStyle: { color: withAlpha(tokens.fgFaint, 0.06), ...cell, borderWidth: 3 },
        dayLabel: {
          firstDay: 1,
          nameMap: ["S", "M", "T", "W", "T", "F", "S"],
          color: tokens.fgFaint,
          fontFamily: tokens.font,
          fontSize: 10,
        },
        monthLabel: { color: tokens.fgMuted, fontFamily: tokens.font, fontSize: 11 },
        yearLabel: { show: false },
      },
      series: [
        {
          type: "heatmap",
          coordinateSystem: "calendar",
          itemStyle: { ...cell, borderWidth: 3 },
          data: days.map((day) => [day.date, day.value]),
        },
      ],
    } as EChartsOption
  }

  const xs = spec.xLabels ?? unique(data.map((entry) => entry.x))
  const ys = spec.yLabels ?? unique(data.map((entry) => entry.y))
  const showValues = values ?? data.length <= 80
  // Strong cells sit near the end of the ramp, so they take whichever ink reads on that end.
  const inkAt = (value: number) =>
    inkOn(
      tokens,
      scheme === "diverging"
        ? value < 0
          ? tokens.danger
          : tokens.success
        : tokens.accent,
    )
  const strong = (value: number) =>
    scheme === "diverging"
      ? Math.abs(value) / reach > 0.55
      : (value - min) / (max - min) > 0.55

  return {
    visualMap,
    grid: { left: 4, right: 8, top: 8, bottom, containLabel: true },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const [x, y, value] = (params as { value: [number, number, number | null] })
          .value
        return tooltipHtml(ys[y] ?? "", [
          { name: xs[x] ?? "", value: value === null ? "n/a" : print(value) },
        ])
      },
    },
    xAxis: {
      ...categoryAxis(tokens, xs),
      axisLine: { show: false },
      splitArea: { show: false },
    },
    yAxis: {
      ...categoryAxis(tokens, ys),
      inverse: true,
      axisLine: { show: false },
      splitArea: { show: false },
    },
    series: [
      {
        type: "heatmap",
        itemStyle: cell,
        emphasis: { itemStyle: { borderColor: tokens.fg, borderWidth: 1.5 } },
        label: {
          show: showValues,
          color: tokens.fg,
          fontFamily: tokens.fontMono,
          fontSize: 10,
          formatter: (params: { value: [number, number, number | null] }) =>
            params.value[2] === null ? "" : print(params.value[2]),
        },
        data: data.flatMap((entry) => {
          const x = xs.indexOf(entry.x)
          const y = ys.indexOf(entry.y)
          if (x < 0 || y < 0) return []
          return [
            {
              value: [x, y, entry.value],
              ...(entry.value !== null && strong(entry.value)
                ? { label: { color: inkAt(entry.value) } }
                : {}),
            },
          ]
        }),
      },
    ],
  } as EChartsOption
}

export const heatmapChartTable = ({
  data = [],
  days,
  xLabels,
  yLabels,
  format,
}: HeatmapChartSpec): ChartSummary => {
  const print = toFormatter(format)
  const cell = (value: number | null | undefined) =>
    value === null || value === undefined ? null : print(value)
  if (days)
    return {
      columns: ["Date", "Value"],
      rows: days.map((day) => [day.date, cell(day.value)]),
    }
  const xs = xLabels ?? unique(data.map((entry) => entry.x))
  const ys = yLabels ?? unique(data.map((entry) => entry.y))
  return {
    columns: ["", ...xs],
    rows: ys.map((y) => [
      y,
      ...xs.map((x) =>
        cell(data.find((entry) => entry.x === x && entry.y === y)?.value),
      ),
    ]),
  }
}

export interface HeatmapChartProps extends ChartCommonProps, HeatmapChartSpec {}

/** Intensity across two categories, or per day on a calendar. */
export const HeatmapChart = specChart<HeatmapChartSpec>({
  name: "HeatmapChart",
  keys: ["data", "days", "xLabels", "yLabels", "format", "scheme", "values", "scale"],
  option: heatmapChartOption,
  table: heatmapChartTable,
  isEmpty: (spec) => (spec.days ?? spec.data ?? []).length === 0,
  label: "Heatmap",
  height: (spec) =>
    spec.days
      ? 220
      : Math.max(
          (spec.yLabels ?? unique((spec.data ?? []).map((entry) => entry.y))).length *
            36 +
            80,
          180,
        ),
})

"use client"

import type { ChartCommonProps, ChartSummary } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, formatPercent, toFormatter } from "./format"
import { tooltipBase, tooltipHtml } from "./option-parts"
import { inkOn, specChart } from "./spec-chart"
import { type ChartTokens, type ChartTone, colorOf, withAlpha } from "./tokens"

export interface SunburstChartNode {
  label: string
  /** A leaf's size. A parent without one is the sum of its children. */
  value?: number
  /** Top-level nodes take the next palette color, and their branch inherits it. */
  color?: ChartTone | string
  children?: SunburstChartNode[]
}

export type TreemapChartNode = SunburstChartNode

export interface SunburstChartSpec {
  data: SunburstChartNode[]
  format?: ChartFormat
  /** Names on the segments. */
  labels?: boolean
}

export type TreemapChartSpec = SunburstChartSpec

const sizeOf = (node: SunburstChartNode): number =>
  node.value ?? (node.children ?? []).reduce((sum, child) => sum + sizeOf(child), 0)

interface Painted {
  name: string
  value: number
  path: string
  itemStyle: { color: string }
  label: { color: string }
  children?: Painted[]
}

// Each ring outward fades a step toward the surface, so a branch reads as one hue.
const paint = (
  tokens: ChartTokens,
  nodes: readonly SunburstChartNode[],
  depth = 0,
  inherited?: string,
  trail = "",
): Painted[] =>
  nodes.map((node, index) => {
    const own =
      depth === 0 || node.color ? colorOf(tokens, node.color, index) : (inherited ?? "")
    const path = trail ? `${trail} / ${node.label}` : node.label
    const color =
      node.color || depth === 0 ? own : withAlpha(own, Math.max(1 - depth * 0.24, 0.35))
    return {
      name: node.label,
      value: sizeOf(node),
      path,
      itemStyle: { color },
      label: { color: inkOn(tokens, color) },
      ...(node.children?.length
        ? { children: paint(tokens, node.children, depth + 1, own, path) }
        : {}),
    }
  })

// Treemap tiles carry their labels, so they take light washes of the branch hue for the ink.
const soften = (tokens: ChartTokens, nodes: readonly Painted[]): Painted[] =>
  nodes.map((node) => {
    const color = withAlpha(node.itemStyle.color, node.children ? 0.55 : 0.34)
    return {
      ...node,
      itemStyle: { color },
      label: { color: inkOn(tokens, color) },
      ...(node.children ? { children: soften(tokens, node.children) } : {}),
    }
  })

const tooltip = (
  tokens: ChartTokens,
  total: number,
  format: (v: number) => string,
) => ({
  ...tooltipBase(tokens),
  trigger: "item" as const,
  formatter: (params: unknown) => {
    const hit = params as { data?: Painted; color: string }
    if (!hit.data?.path) return ""
    return tooltipHtml(hit.data.path, [
      { name: "Value", color: hit.color, value: format(hit.data.value) },
      {
        name: "Of total",
        value: formatPercent(total > 0 ? hit.data.value / total : 0),
      },
    ])
  },
})

export const sunburstChartOption = (
  { data, labels = true, ...spec }: SunburstChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const total = data.reduce((sum, node) => sum + sizeOf(node), 0)
  return {
    tooltip: tooltip(tokens, total, format),
    series: [
      {
        type: "sunburst",
        radius: ["16%", width > 0 && width < 420 ? "94%" : "90%"],
        sort: undefined,
        nodeClick: false,
        itemStyle: { borderColor: tokens.surface, borderWidth: 2, borderRadius: 3 },
        emphasis: { focus: "ancestor" },
        blur: { itemStyle: { opacity: 0.3 }, label: { opacity: 0.3 } },
        label: {
          show: labels,
          minAngle: 10,
          rotate: "radial",
          color: tokens.fg,
          fontFamily: tokens.font,
          fontSize: 10,
          overflow: "truncate",
        },
        data: paint(tokens, data),
      },
    ],
  } as EChartsOption
}

export const treemapChartOption = (
  { data, labels = true, ...spec }: TreemapChartSpec,
  tokens: ChartTokens,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const total = data.reduce((sum, node) => sum + sizeOf(node), 0)
  const nested = data.some((node) => node.children?.length)
  return {
    tooltip: tooltip(tokens, total, format),
    series: [
      {
        type: "treemap",
        left: 0,
        right: 0,
        top: 0,
        bottom: 0,
        roam: false,
        nodeClick: false,
        breadcrumb: { show: false },
        squareRatio: 1.2,
        label: {
          show: labels,
          position: "insideTopLeft",
          padding: [6, 8],
          formatter: (params: { name: string; value: number }) =>
            `{name|${params.name}}\n{value|${format(params.value)}}`,
          rich: {
            name: {
              color: tokens.fg,
              fontFamily: tokens.font,
              fontSize: 11,
              lineHeight: 15,
            },
            value: {
              color: tokens.fgMuted,
              fontFamily: tokens.fontMono,
              fontSize: 10,
              lineHeight: 14,
            },
          },
        },
        upperLabel: {
          show: nested && labels,
          height: 22,
          color: tokens.fg,
          fontFamily: tokens.font,
          fontSize: 11,
          fontWeight: 600,
          padding: [0, 8],
          formatter: (params: { name: string }) => params.name,
        },
        // levels[0] is the invisible root, so the first visible level is levels[1].
        levels: [
          { itemStyle: { borderWidth: 0, gapWidth: 3 }, upperLabel: { show: false } },
          {
            itemStyle: {
              borderColor: tokens.surface,
              borderWidth: nested ? 2 : 0,
              gapWidth: 2,
              borderRadius: 6,
            },
          },
          { itemStyle: { borderWidth: 0, gapWidth: 1, borderRadius: 3 } },
        ],
        data: soften(tokens, paint(tokens, data)),
      },
    ],
  } as EChartsOption
}

export const hierarchyTable = ({ data, format }: SunburstChartSpec): ChartSummary => {
  const print = toFormatter(format)
  const rows: (string | number | null)[][] = []
  const walk = (nodes: readonly SunburstChartNode[], trail: string) => {
    for (const node of nodes) {
      const path = trail ? `${trail} / ${node.label}` : node.label
      if (node.children?.length) walk(node.children, path)
      else rows.push([path, print(sizeOf(node))])
    }
  }
  walk(data, "")
  return { columns: ["Path", "Value"], rows }
}

export interface SunburstChartProps extends ChartCommonProps, SunburstChartSpec {}
export interface TreemapChartProps extends ChartCommonProps, TreemapChartSpec {}

/** A hierarchy as rings: the centre is the whole, each ring outward a level down. */
export const SunburstChart = specChart<SunburstChartSpec>({
  name: "SunburstChart",
  keys: ["data", "format", "labels"],
  option: sunburstChartOption,
  table: hierarchyTable,
  isEmpty: (spec) => spec.data.length === 0,
  label: "Sunburst chart",
  height: 360,
})

/** A hierarchy as nested tiles, each sized by its value. */
export const TreemapChart = specChart<TreemapChartSpec>({
  name: "TreemapChart",
  keys: ["data", "format", "labels"],
  option: (spec, tokens) => treemapChartOption(spec, tokens),
  table: hierarchyTable,
  isEmpty: (spec) => spec.data.length === 0,
  label: "Treemap",
  height: 340,
})

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, formatPercent, toFormatter } from "./format"
import { tooltipBase, tooltipHtml, valueAxis } from "./option-parts"
import { type CustomApi, type CustomParams, median, specChart } from "./spec-chart"
import { type ChartTokens, type ChartTone, colorOf, withAlpha } from "./tokens"

export interface HistogramChartBin {
  /** Inclusive lower edge. */
  x0: number
  /** Exclusive upper edge, inclusive for the last bin. */
  x1: number
  count: number
}

export interface HistogramChartSpec {
  /** Raw observations. */
  values: number[]
  /** Target bin count. Picked by the Freedman-Diaconis rule otherwise, then rounded to a nice step. */
  bins?: number
  format?: ChartFormat
  color?: ChartTone | string
  /** A dashed rule at the median. */
  showMedian?: boolean
}

const niceStep = (rough: number): number => {
  if (!(rough > 0)) return 1
  const power = 10 ** Math.floor(Math.log10(rough))
  const fraction = rough / power
  const nice = fraction <= 1 ? 1 : fraction <= 2 ? 2 : fraction <= 2.5 ? 2.5 : fraction <= 5 ? 5 : 10
  return nice * power
}

const roughCount = (sorted: readonly number[]): number => {
  const n = sorted.length
  const at = (p: number) => sorted[Math.floor((n - 1) * p)] ?? 0
  const iqr = at(0.75) - at(0.25)
  const span = (sorted[n - 1] ?? 0) - (sorted[0] ?? 0)
  if (iqr > 0 && span > 0) {
    const width = (2 * iqr) / Math.cbrt(n)
    return Math.min(Math.max(Math.ceil(span / width), 1), 60)
  }
  return Math.max(Math.ceil(Math.log2(n) + 1), 1)
}

/** Equal-width bins on nice edges, so tick labels land on round numbers. */
export const histogramBins = (
  values: readonly number[],
  bins?: number,
): HistogramChartBin[] => {
  const sorted = values.filter(Number.isFinite).sort((a, b) => a - b)
  if (sorted.length === 0) return []
  const low = sorted[0] ?? 0
  const high = sorted[sorted.length - 1] ?? 0
  if (low === high) return [{ x0: low, x1: low + 1, count: sorted.length }]
  const step = niceStep((high - low) / (bins ?? roughCount(sorted)))
  const start = Math.floor(low / step) * step
  const count = Math.max(Math.ceil((high - start) / step), 1)
  // Rounded edges, so float drift never prints 0.30000000000000004.
  const edge = (index: number) => Number((start + index * step).toPrecision(12))
  const out = Array.from({ length: count }, (_, index) => ({
    x0: edge(index),
    x1: edge(index + 1),
    count: 0,
  }))
  for (const value of sorted) {
    const index = Math.min(Math.floor((value - start) / step), count - 1)
    const bin = out[index]
    if (bin) bin.count += 1
  }
  return out
}

// Labelled above the plot, so it never collides with the tick labels along the bottom.
const medianLine = (tokens: ChartTokens, value: number | undefined) =>
  value === undefined
    ? {}
    : {
        markLine: {
          silent: true,
          symbol: "none",
          lineStyle: { color: tokens.fgFaint, type: "dashed", width: 1 },
          label: {
            formatter: "Median",
            position: "end",
            color: tokens.fgMuted,
            fontFamily: tokens.font,
            fontSize: 11,
          },
          data: [{ xAxis: value }],
        },
      }

export const histogramChartOption = (
  { values, bins, color, showMedian = false, ...spec }: HistogramChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const buckets = histogramBins(values, bins)
  const fill = colorOf(tokens, color, 0)
  const total = values.length || 1
  const first = buckets[0]
  const last = buckets[buckets.length - 1]

  return {
    grid: { left: 4, right: 12, top: 16, bottom: 4, containLabel: true },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const bin = buckets[(params as { dataIndex: number }).dataIndex]
        return bin
          ? tooltipHtml(`${format(bin.x0)} to ${format(bin.x1)}`, [
              { name: "Count", color: fill, value: String(bin.count) },
              { name: "Share", value: formatPercent(bin.count / total) },
            ])
          : ""
      },
    },
    xAxis: {
      ...valueAxis(tokens, format, width),
      min: first?.x0,
      max: last?.x1,
      splitLine: { show: false },
      axisLine: { show: true, lineStyle: { color: tokens.border } },
    },
    yAxis: {
      ...valueAxis(tokens, (value) => String(Math.round(value)), width),
      minInterval: 1,
    },
    series: [
      {
        type: "custom",
        name: "Count",
        encode: { x: [0, 1], y: 2 },
        data: buckets.map((bin) => [bin.x0, bin.x1, bin.count]),
        renderItem: (params: CustomParams, api: CustomApi) => {
          const bin = buckets[params.dataIndex]
          if (!bin) return null
          const [left = 0, top = 0] = api.coord([bin.x0, bin.count])
          const [right = 0, bottom = 0] = api.coord([bin.x1, 0])
          // A one pixel gutter keeps neighbouring bins legible without reading as bars.
          return {
            type: "rect",
            shape: {
              x: left + 0.5,
              y: top,
              width: Math.max(right - left - 1, 1),
              height: bottom - top,
              r: [2, 2, 0, 0],
            },
            style: { fill: withAlpha(fill, 0.85) },
            emphasis: { style: { fill } },
          }
        },
        ...medianLine(tokens, showMedian ? median(values) : undefined),
      },
    ],
  } as EChartsOption
}

export interface HistogramChartProps extends ChartCommonProps, HistogramChartSpec {}

/** How raw values distribute: equal-width bins on round edges, binned in the browser. */
export const HistogramChart = specChart<HistogramChartSpec>({
  name: "HistogramChart",
  keys: ["values", "bins", "format", "color", "showMedian"],
  option: histogramChartOption,
  table: (spec) => {
    const print = toFormatter(spec.format)
    return {
      columns: ["From", "To", "Count"],
      rows: histogramBins(spec.values, spec.bins).map((bin) => [
        print(bin.x0),
        print(bin.x1),
        bin.count,
      ]),
    }
  },
  isEmpty: (spec) => spec.values.length === 0,
  label: "Histogram",
  height: 280,
})

"use client"

import { forwardRef, useCallback, useMemo } from "react"
import { Chart, type ChartCommonProps, useStableSpec } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, formatPercent, toFormatter } from "./format"
import {
  areaFade,
  axisParams,
  type ChartLegend,
  type ChartReference,
  type ChartRow,
  type ChartSeriesInput,
  categoryAxis,
  lastPointMark,
  legendOption,
  legendRoom,
  numberAt,
  referenceLine,
  resolveSeries,
  seriesEntries,
  tableOf,
  tooltipBase,
  tooltipHtml,
  valueAxis,
} from "./option-parts"
import { type ChartTokens, withAlpha } from "./tokens"

export type LineChartCurve = "linear" | "smooth" | "step"
export type AreaChartMode = "stacked" | "overlap" | "percent" | "stream"

export interface LineChartSpec {
  data: ChartRow[]
  /** The field that labels the category axis. */
  xKey: string
  /** Fields to plot. Every numeric field but `xKey` when omitted. */
  series?: ChartSeriesInput[]
  format?: ChartFormat
  curve?: LineChartCurve
  /** Fills under each line. */
  area?: boolean
  stacked?: boolean
  /** Draws a dot on every point, not only the latest. */
  points?: boolean
  legend?: ChartLegend
  reference?: ChartReference
}

export interface AreaChartSpec extends Omit<LineChartSpec, "area" | "stacked"> {
  /** `percent` stacks to 100%; `stream` stacks around a centre line. */
  mode?: AreaChartMode
}

interface TrendSpec extends Omit<LineChartSpec, "stacked"> {
  mode: AreaChartMode | "none"
}

const trendOption = (
  spec: TrendSpec,
  tokens: ChartTokens,
  width: number,
): EChartsOption => {
  const { data, xKey, mode, curve = "linear", area = false } = spec
  const format = toFormatter(spec.format)
  const series = resolveSeries(tokens, data, xKey, spec.series)
  const labels = data.map((row) => String(row[xKey] ?? ""))
  const stacked = mode === "stacked" || mode === "percent" || mode === "stream"
  const totals = data.map((row) =>
    series.reduce((sum, entry) => sum + (numberAt(row, entry.key) ?? 0), 0),
  )
  const share = (value: number, index: number) => {
    const total = totals[index] ?? 0
    return total === 0 ? 0 : value / total
  }
  const legend = legendOption(tokens, spec.legend, series.length)
  const room = legendRoom(legend)
  const smooth = curve === "smooth" ? 0.35 : false
  const step = curve === "step" ? ("middle" as const) : false
  // A stream is a stack resting on an invisible base at minus half the total.
  const base = mode === "stream" ? 1 : 0

  const lines = series.map((entry, index) => {
    const values = data.map((row, at) => {
      const value = numberAt(row, entry.key)
      if (value === null) return null
      return mode === "percent" ? share(value, at) : value
    })
    return {
      type: "line" as const,
      name: entry.label,
      color: entry.color,
      data: values,
      smooth,
      smoothMonotone: "x" as const,
      step,
      stack: stacked ? "total" : undefined,
      showSymbol: spec.points ?? false,
      symbol: "circle",
      symbolSize: 6,
      lineStyle: {
        width: stacked ? 1.5 : 2,
        color: entry.color,
        type: entry.dashed ? ("dashed" as const) : ("solid" as const),
        cap: "round" as const,
        join: "round" as const,
      },
      itemStyle: { color: entry.color, borderColor: tokens.surface, borderWidth: 1.5 },
      ...(area
        ? {
            areaStyle: stacked
              ? { color: withAlpha(entry.color, 0.82), opacity: 1 }
              : { color: areaFade(entry.color), opacity: 1 },
          }
        : {}),
      emphasis: { focus: "series" as const },
      blur: { lineStyle: { opacity: 0.25 }, areaStyle: { opacity: 0.2 } },
      ...(index === 0 ? referenceLine(tokens, spec.reference, "yAxis") : {}),
      ...(!stacked && !entry.dashed ? lastPointMark(tokens, entry.color, values) : {}),
    }
  })

  const offset =
    mode === "stream"
      ? [
          {
            type: "line" as const,
            name: "",
            data: totals.map((total) => -total / 2),
            stack: "total",
            smooth,
            smoothMonotone: "x" as const,
            step,
            silent: true,
            showSymbol: false,
            lineStyle: { opacity: 0 },
            tooltip: { show: false },
          },
        ]
      : []

  const axis = valueAxis(
    tokens,
    mode === "percent" ? (v) => formatPercent(v, 0) : format,
    width,
  )

  return {
    grid: {
      left: 4,
      right: 16,
      top: room.top,
      bottom: room.bottom,
      containLabel: true,
    },
    legend: { ...legend, data: series.map((entry) => entry.label) },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "axis",
      axisPointer: { type: "line", lineStyle: { color: tokens.border, width: 1 } },
      formatter: (params: unknown) => {
        const hits = axisParams(params).filter((hit) => hit.seriesIndex >= base)
        const at = hits[0]?.dataIndex ?? -1
        const row = data[at]
        if (!row) return ""
        return tooltipHtml(
          labels[at] ?? "",
          hits.flatMap((hit) => {
            const entry = series[hit.seriesIndex - base]
            if (!entry) return []
            const value = numberAt(row, entry.key)
            const printed =
              value === null
                ? "n/a"
                : mode === "percent"
                  ? `${format(value)} (${formatPercent(share(value, at))})`
                  : format(value)
            return [{ name: entry.label, color: entry.color, value: printed }]
          }),
        )
      },
    },
    xAxis: { ...categoryAxis(tokens, labels), boundaryGap: false },
    yAxis:
      mode === "stream"
        ? { type: "value", show: false }
        : mode === "percent"
          ? { ...axis, max: 1 }
          : axis,
    series: [...offset, ...lines],
  } as EChartsOption
}

export const lineChartOption = (
  { stacked = false, ...spec }: LineChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption =>
  trendOption({ ...spec, mode: stacked ? "stacked" : "none" }, tokens, width)

export const areaChartOption = (
  { mode = "stacked", curve = "smooth", ...spec }: AreaChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption =>
  trendOption(
    { ...spec, curve, area: true, mode: mode === "overlap" ? "none" : mode },
    tokens,
    width,
  )

export interface LineChartProps extends ChartCommonProps, LineChartSpec {}
export interface AreaChartProps extends ChartCommonProps, AreaChartSpec {}

const useTable = (
  summary: boolean,
  data: ChartRow[],
  xKey: string,
  series: ChartSeriesInput[] | undefined,
  format: ChartFormat | undefined,
) =>
  useMemo(
    () =>
      summary
        ? tableOf(data, xKey, seriesEntries(data, xKey, series), toFormatter(format))
        : undefined,
    [summary, data, xKey, series, format],
  )

/** Lines over shared ticks: trends, comparisons, smooth or stepped, filled or not. */
export const LineChart = forwardRef<HTMLDivElement, LineChartProps>(
  (
    {
      data,
      xKey,
      series,
      format,
      curve,
      area,
      stacked,
      points,
      legend,
      reference,
      label = "Line chart",
      summary = true,
      empty = "No data to plot",
      ...props
    },
    ref,
  ) => {
    const spec = useStableSpec(
      { data, xKey, series, format, curve, area, stacked, points, legend, reference },
      format,
    )
    const option = useCallback(
      (tokens: ChartTokens, width: number) => lineChartOption(spec, tokens, width),
      [spec],
    )
    const table = useTable(summary, spec.data, spec.xKey, spec.series, spec.format)
    return (
      <Chart
        ref={ref}
        option={option}
        label={label}
        summary={table}
        empty={data.length === 0 ? empty : undefined}
        {...props}
      />
    )
  },
)

LineChart.displayName = "LineChart"

/** Filled bands: stacked composition, overlap, share of 100%, or a stream. */
export const AreaChart = forwardRef<HTMLDivElement, AreaChartProps>(
  (
    {
      data,
      xKey,
      series,
      format,
      curve,
      mode,
      points,
      legend,
      reference,
      label = "Area chart",
      summary = true,
      empty = "No data to plot",
      ...props
    },
    ref,
  ) => {
    const spec = useStableSpec(
      { data, xKey, series, format, curve, mode, points, legend, reference },
      format,
    )
    const option = useCallback(
      (tokens: ChartTokens, width: number) => areaChartOption(spec, tokens, width),
      [spec],
    )
    const table = useTable(summary, spec.data, spec.xKey, spec.series, spec.format)
    return (
      <Chart
        ref={ref}
        option={option}
        label={label}
        summary={table}
        empty={data.length === 0 ? empty : undefined}
        {...props}
      />
    )
  },
)

AreaChart.displayName = "AreaChart"

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import {
  type ChartDatum,
  type ChartReference,
  categoryAxis,
  datumTable,
  referenceLine,
  sortData,
  tooltipBase,
  tooltipHtml,
  valueAxis,
} from "./option-parts"
import { specChart } from "./spec-chart"
import { type ChartTokens, colorOf, withAlpha } from "./tokens"

export interface LollipopChartSpec {
  data: ChartDatum[]
  format?: ChartFormat
  orientation?: "horizontal" | "vertical"
  sort?: "desc" | "asc" | "none"
  /** Prints each value beside its dot. On by default. */
  labels?: boolean
  reference?: ChartReference
}

const ROW = 30

export const lollipopChartOption = (
  {
    data,
    orientation = "horizontal",
    sort = "desc",
    labels = true,
    reference,
    ...spec
  }: LollipopChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const rows = sortData(data, sort)
  const sideways = orientation === "horizontal"
  const colors = rows.map((datum) => colorOf(tokens, datum.color, 0))
  const category = {
    ...categoryAxis(
      tokens,
      rows.map((datum) => datum.label),
    ),
    ...(sideways
      ? {
          inverse: true,
          axisLine: { show: false },
          axisLabel: { ...categoryAxis(tokens, []).axisLabel, interval: 0 },
        }
      : {}),
  }
  const value = valueAxis(tokens, format, width)
  const point = (datum: ChartDatum, index: number) =>
    sideways ? [datum.value, index] : [index, datum.value]

  return {
    grid: { left: 4, right: labels && sideways ? 48 : 16, top: 20, bottom: 4, containLabel: true },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const index = (params as { dataIndex: number }).dataIndex
        const datum = rows[index]
        return datum
          ? tooltipHtml(datum.label, [
              { name: "Value", color: colors[index], value: format(datum.value) },
            ])
          : ""
      },
    },
    xAxis: sideways ? value : category,
    yAxis: sideways ? category : value,
    series: [
      {
        type: "bar",
        name: "Stem",
        silent: true,
        barWidth: 2,
        data: rows.map((datum, index) => ({
          value: datum.value,
          itemStyle: { color: withAlpha(colors[index] ?? tokens.accent, 0.45) },
        })),
        ...referenceLine(tokens, reference, sideways ? "xAxis" : "yAxis"),
      },
      {
        type: "scatter",
        name: "Value",
        symbolSize: 12,
        z: 3,
        emphasis: { scale: 1.3 },
        label: {
          show: labels,
          position: sideways ? "right" : "top",
          distance: 8,
          color: tokens.fg,
          fontFamily: tokens.fontMono,
          fontSize: 11,
          fontWeight: 600,
          formatter: (params: { dataIndex: number }) =>
            format(rows[params.dataIndex]?.value ?? 0),
        },
        data: rows.map((datum, index) => ({
          value: point(datum, index),
          itemStyle: {
            color: colors[index],
            borderColor: tokens.surface,
            borderWidth: 2,
          },
        })),
      },
    ],
  } as EChartsOption
}

export interface LollipopChartProps extends ChartCommonProps, LollipopChartSpec {}

/** A ranked bar chart with less ink: a thin stem and a dot at the value. */
export const LollipopChart = specChart<LollipopChartSpec>({
  name: "LollipopChart",
  keys: ["data", "format", "orientation", "sort", "labels", "reference"],
  option: lollipopChartOption,
  table: (spec) => datumTable(sortData(spec.data, spec.sort ?? "desc"), toFormatter(spec.format)),
  isEmpty: (spec) => spec.data.length === 0,
  label: "Lollipop chart",
  height: (spec) =>
    spec.orientation === "vertical" ? 300 : Math.max(spec.data.length * ROW + 40, 160),
})

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, formatPercent, toFormatter } from "./format"
import {
  type ChartLegend,
  type ChartRow,
  type ChartSeriesInput,
  legendOption,
  legendRoom,
  numberAt,
  resolveSeries,
  seriesEntries,
  tableOf,
  tooltipBase,
  tooltipHtml,
} from "./option-parts"
import { type CustomApi, type CustomParams, inkOn, specChart } from "./spec-chart"
import type { ChartTokens } from "./tokens"

export interface MekkoChartSpec {
  /** One column per row: its width is the row's share of the grand total. */
  data: ChartRow[]
  xKey: string
  /** The stacked segments; each is sized by its share of its own column. */
  series?: ChartSeriesInput[]
  format?: ChartFormat
  /** Prints each segment's share where it fits. */
  values?: boolean
  legend?: ChartLegend
}

export interface MekkoChartBlock {
  column: number
  series: number
  value: number
  /** Edges in shares of the whole width and of the column height, 0 to 1. */
  x0: number
  x1: number
  y0: number
  y1: number
}

/** Columns as wide as their total, segments as tall as their share of the column. */
export const mekkoBlocks = (
  data: readonly ChartRow[],
  keys: readonly string[],
): { blocks: MekkoChartBlock[]; totals: number[]; grand: number } => {
  const totals = data.map((row) =>
    keys.reduce((sum, key) => sum + Math.max(numberAt(row, key) ?? 0, 0), 0),
  )
  const grand = totals.reduce((sum, total) => sum + total, 0)
  const blocks: MekkoChartBlock[] = []
  let left = 0
  data.forEach((row, column) => {
    const total = totals[column] ?? 0
    const right = grand > 0 ? left + total / grand : left
    let bottom = 0
    keys.forEach((key, series) => {
      const value = Math.max(numberAt(row, key) ?? 0, 0)
      const top = total > 0 ? bottom + value / total : bottom
      if (value > 0)
        blocks.push({ column, series, value, x0: left, x1: right, y0: bottom, y1: top })
      bottom = top
    })
    left = right
  })
  return { blocks, totals, grand }
}

export const mekkoChartOption = (
  { data, xKey, values = true, ...spec }: MekkoChartSpec,
  tokens: ChartTokens,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const series = resolveSeries(tokens, data, xKey, spec.series)
  const { blocks, totals, grand } = mekkoBlocks(
    data,
    series.map((entry) => entry.key),
  )
  const labels = data.map((row) => String(row[xKey] ?? ""))
  const legend = legendOption(tokens, spec.legend, series.length)
  const room = legendRoom(legend)
  const share = { axisLabel: { formatter: (value: number) => formatPercent(value, 0) } }
  const axis = {
    type: "value" as const,
    min: 0,
    max: 1,
    axisLine: { show: false },
    axisTick: { show: false },
    splitLine: { show: false },
  }

  return {
    legend: { ...legend, data: series.map((entry) => entry.label) },
    grid: {
      left: 4,
      right: 8,
      top: room.top,
      bottom: room.bottom + 34,
      containLabel: true,
    },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const hit = params as { seriesIndex: number; dataIndex: number; color: string }
        const block = blocks.filter((entry) => entry.series === hit.seriesIndex)[
          hit.dataIndex
        ]
        if (!block) return ""
        const total = totals[block.column] ?? 0
        return tooltipHtml(labels[block.column] ?? "", [
          {
            name: series[block.series]?.label ?? "",
            color: hit.color,
            value: format(block.value),
          },
          {
            name: "Share of column",
            value: formatPercent(total ? block.value / total : 0),
          },
          { name: "Column of total", value: formatPercent(grand ? total / grand : 0) },
        ])
      },
    },
    xAxis: { ...axis, axisLabel: { show: false } },
    yAxis: {
      ...axis,
      axisLabel: {
        ...share.axisLabel,
        color: tokens.fgFaint,
        fontFamily: tokens.fontMono,
        fontSize: 11,
      },
    },
    series: series.map((entry, index) => {
      const own = blocks.filter((block) => block.series === index)
      return {
        type: "custom",
        name: entry.label,
        color: entry.color,
        encode: { x: [0, 1], y: [2, 3] },
        data: own.map((block) => [block.x0, block.x1, block.y0, block.y1]),
        emphasis: { focus: "series" },
        renderItem: (params: CustomParams, api: CustomApi) => {
          const ink = inkOn(tokens, entry.color)
          const block = own[params.dataIndex]
          if (!block) return null
          const [left = 0, bottom = 0] = api.coord([block.x0, block.y0])
          const [right = 0, top = 0] = api.coord([block.x1, block.y1])
          const width = right - left
          const height = bottom - top
          const total = totals[block.column] ?? 0
          const children: unknown[] = [
            {
              type: "rect",
              shape: { x: left, y: top, width, height },
              style: { fill: entry.color, stroke: tokens.surface, lineWidth: 2 },
            },
          ]
          if (values && width > 40 && height > 18)
            children.push({
              type: "text",
              silent: true,
              x: left + 6,
              y: top + 5,
              style: {
                text: formatPercent(total ? block.value / total : 0, 0),
                fill: ink,
                font: `600 11px ${tokens.fontMono}`,
              },
            })
          // The bottom block of each column carries the column's name and its share.
          if (block.y0 === 0)
            children.push({
              type: "text",
              silent: true,
              x: left + width / 2,
              y: bottom + 8,
              style: {
                text: `${labels[block.column] ?? ""}\n${formatPercent(grand ? total / grand : 0, 0)}`,
                fill: tokens.fgMuted,
                font: `11px ${tokens.font}`,
                align: "center",
                lineHeight: 15,
                width: Math.max(width - 4, 8),
                overflow: "truncate",
              },
            })
          return { type: "group", children }
        },
      }
    }),
  } as EChartsOption
}

export interface MekkoChartProps extends ChartCommonProps, MekkoChartSpec {}

/** Two shares at once: column width is each row's weight, segment height its mix. */
export const MekkoChart = specChart<MekkoChartSpec>({
  name: "MekkoChart",
  keys: ["data", "xKey", "series", "format", "values", "legend"],
  option: (spec, tokens) => mekkoChartOption(spec, tokens),
  table: (spec) =>
    tableOf(
      spec.data,
      spec.xKey,
      seriesEntries(spec.data, spec.xKey, spec.series),
      toFormatter(spec.format),
    ),
  isEmpty: (spec) => spec.data.length === 0,
  label: "Marimekko chart",
  height: 360,
})

import type { EChartsOption } from "./echarts"
import type { ChartFormatter } from "./format"
import { type ChartTokens, type ChartTone, colorOf, withAlpha } from "./tokens"

export type ChartRow = Record<string, string | number | null | undefined>

export interface ChartSeries {
  /** The field of each row that holds this series' values. */
  key: string
  label?: string
  /** A tone, any CSS color (`var()` works), or the next palette color when omitted. */
  color?: ChartTone | string
  dashed?: boolean
}

export type ChartSeriesInput = string | ChartSeries

export interface ChartReference {
  value: number
  label?: string
}

/** `true` places the legend on top. Omitted, it shows only when there are several series. */
export type ChartLegend = boolean | "top" | "bottom"

export interface ResolvedSeries {
  key: string
  label: string
  color: string
  dashed: boolean
}

type Loose = Record<string, unknown>

const isObject = (value: unknown): value is Loose =>
  typeof value === "object" && value !== null && !Array.isArray(value)

/** Every numeric field but `xKey` when `series` is omitted. */
export const seriesEntries = (
  data: readonly ChartRow[],
  xKey: string,
  series: readonly ChartSeriesInput[] | undefined,
): ChartSeries[] =>
  (series
    ? [...series]
    : Object.keys(data[0] ?? {}).filter(
        (key) => key !== xKey && data.some((row) => typeof row[key] === "number"),
      )
  ).map((input) => (typeof input === "string" ? { key: input } : input))

export const resolveSeries = (
  tokens: ChartTokens,
  data: readonly ChartRow[],
  xKey: string,
  series: readonly ChartSeriesInput[] | undefined,
  offset = 0,
): ResolvedSeries[] =>
  seriesEntries(data, xKey, series).map((entry, index) => ({
    key: entry.key,
    label: entry.label ?? entry.key,
    color: colorOf(tokens, entry.color, index + offset),
    dashed: entry.dashed ?? false,
  }))

export const numberAt = (row: ChartRow | undefined, key: string): number | null => {
  const value = row?.[key]
  return typeof value === "number" && Number.isFinite(value) ? value : null
}

const ENTITIES: Record<string, string> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
}

/** Tooltips are HTML, and labels come from data. */
export const escapeHtml = (value: unknown): string =>
  String(value ?? "").replace(/[&<>"']/g, (char) => ENTITIES[char] ?? char)

export interface TooltipLine {
  name: string
  color?: string
  value: string
}

export const tooltipHtml = (title: string, lines: readonly TooltipLine[]): string =>
  (title ? `<div class="kg-chart-tooltip__title">${escapeHtml(title)}</div>` : "") +
  lines
    .map(
      (line) =>
        `<div class="kg-chart-tooltip__row">` +
        (line.color
          ? `<span class="kg-chart-tooltip__swatch" style="background:${escapeHtml(line.color)}"></span>`
          : "") +
        `<span class="kg-chart-tooltip__name">${escapeHtml(line.name)}</span>` +
        `<span class="kg-chart-tooltip__value">${escapeHtml(line.value)}</span></div>`,
    )
    .join("")

export const tooltipBase = (tokens: ChartTokens) => ({
  className: "kg-chart-tooltip",
  backgroundColor: "transparent",
  borderWidth: 0,
  padding: 0,
  confine: true,
  transitionDuration: 0,
  textStyle: { color: tokens.fg, fontFamily: tokens.font, fontSize: 12 },
})

export const legendOption = (
  tokens: ChartTokens,
  legend: ChartLegend | undefined,
  count: number,
): { show: boolean; top?: number; bottom?: number } & Record<string, unknown> => {
  const place = legend === undefined ? (count > 1 ? "top" : false) : legend
  if (place === false) return { show: false }
  return {
    show: true,
    type: "scroll" as const,
    ...(place === "bottom" ? { bottom: 0 } : { top: 0 }),
    left: 0,
    icon: "roundRect",
    itemWidth: 10,
    itemHeight: 10,
    itemGap: 16,
    textStyle: { color: tokens.fgMuted, fontFamily: tokens.font, fontSize: 12 },
    inactiveColor: tokens.fgFaint,
    pageIconColor: tokens.fgMuted,
    pageIconInactiveColor: tokens.border,
    pageIconSize: 9,
    pageTextStyle: { color: tokens.fgFaint, fontSize: 10 },
  }
}

export const legendRoom = (legend: { show: boolean; bottom?: number }) => ({
  top: legend.show && legend.bottom === undefined ? 36 : 12,
  bottom: legend.show && legend.bottom !== undefined ? 32 : 4,
})

export const categoryAxis = (tokens: ChartTokens, labels: readonly string[]) => ({
  type: "category" as const,
  data: [...labels],
  axisLine: { lineStyle: { color: tokens.border } },
  axisTick: { show: false },
  axisLabel: {
    color: tokens.fgMuted,
    fontFamily: tokens.font,
    fontSize: 11,
    hideOverlap: true,
    margin: 10,
  },
})

export const valueAxis = (tokens: ChartTokens, format: ChartFormatter, width = 0) => ({
  type: "value" as const,
  axisLine: { show: false },
  axisTick: { show: false },
  // A phone fits about four tick labels; the default seven run together.
  splitNumber: width > 0 && width < 420 ? 3 : undefined,
  splitLine: { lineStyle: { color: tokens.grid, type: "dashed" as const, width: 1 } },
  // ECharts passes `(value, index)`; a formatter with optional digits would read the index.
  axisLabel: {
    color: tokens.fgFaint,
    fontFamily: tokens.fontMono,
    fontSize: 11,
    hideOverlap: true,
    margin: 10,
    formatter: (value: number) => format(value),
  },
})

export const referenceLine = (
  tokens: ChartTokens,
  reference: ChartReference | undefined,
  axis: "xAxis" | "yAxis",
) =>
  reference
    ? {
        markLine: {
          silent: true,
          symbol: "none",
          lineStyle: { color: tokens.fgFaint, type: "dashed", width: 1 },
          label: {
            show: Boolean(reference.label),
            formatter: reference.label ?? "",
            color: tokens.fgMuted,
            fontFamily: tokens.font,
            fontSize: 11,
            // Horizontal bars run an inverse category axis, which puts a vertical line's start on top.
            position: axis === "yAxis" ? "insideEndTop" : "start",
          },
          data: [{ [axis]: reference.value }],
        },
      }
    : {}

/** Full color at the cap, easing toward the baseline. */
export const barFill = (color: string, sideways = false) => ({
  type: "linear" as const,
  x: sideways ? 1 : 0,
  y: 0,
  x2: 0,
  y2: sideways ? 0 : 1,
  colorStops: [
    { offset: 0, color },
    { offset: 1, color: withAlpha(color, 0.72) },
  ],
})

/** A wash that falls from the line to nothing, so the line stays the subject. */
export const areaFade = (color: string) => ({
  type: "linear" as const,
  x: 0,
  y: 0,
  x2: 0,
  y2: 1,
  colorStops: [
    { offset: 0, color: withAlpha(color, 0.3) },
    { offset: 1, color: withAlpha(color, 0) },
  ],
})

/** The latest value wears a dot ringed in the surface color. */
export const lastPointMark = (
  tokens: ChartTokens,
  color: string,
  values: readonly (number | null)[],
) => {
  for (let index = values.length - 1; index >= 0; index--) {
    const value = values[index]
    if (value == null) continue
    return {
      markPoint: {
        silent: true,
        animation: false,
        symbol: "circle",
        symbolSize: 8,
        label: { show: false },
        itemStyle: { color, borderColor: tokens.surface, borderWidth: 2 },
        data: [{ coord: [index, value] }],
      },
    }
  }
  return {}
}

export const tableOf = (
  data: readonly ChartRow[],
  xKey: string,
  series: readonly ChartSeries[],
  format: ChartFormatter,
) => ({
  columns: [xKey, ...series.map((entry) => entry.label ?? entry.key)],
  rows: data.map((row) => [
    String(row[xKey] ?? ""),
    ...series.map((entry) => {
      const value = numberAt(row, entry.key)
      return value === null ? null : format(value)
    }),
  ]),
})

export interface ChartDatum {
  label: string
  value: number
  color?: ChartTone | string
}

export const datumTable = (data: readonly ChartDatum[], format: ChartFormatter) => ({
  columns: ["Label", "Value"],
  rows: data.map((datum) => [datum.label, format(datum.value)]),
})

export const sortData = (
  data: readonly ChartDatum[],
  sort: "desc" | "asc" | "none",
): ChartDatum[] =>
  sort === "none"
    ? [...data]
    : [...data].sort((a, b) =>
        sort === "desc" ? b.value - a.value : a.value - b.value,
      )

/** Palette, font and tooltip shell for any option, a raw escape-hatch one included. */
export const themeOption = (
  option: EChartsOption,
  tokens: ChartTokens,
): EChartsOption => {
  const loose = option as Loose
  const tooltip = loose.tooltip
  return {
    color: [...tokens.palette],
    backgroundColor: "transparent",
    textStyle: { fontFamily: tokens.font, color: tokens.fgMuted, fontSize: 11 },
    animationDuration: 560,
    animationEasing: "cubicOut",
    animationDurationUpdate: 360,
    animationEasingUpdate: "cubicInOut",
    ...option,
    ...(isObject(tooltip) ? { tooltip: { ...tooltipBase(tokens), ...tooltip } } : {}),
  } as EChartsOption
}

export interface AxisParam {
  dataIndex: number
  seriesIndex: number
}

export const axisParams = (params: unknown): AxisParam[] =>
  (Array.isArray(params) ? params : [params]).filter(isObject).map((entry) => ({
    dataIndex: typeof entry.dataIndex === "number" ? entry.dataIndex : -1,
    seriesIndex: typeof entry.seriesIndex === "number" ? entry.seriesIndex : -1,
  }))

