import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import {
  axisParams,
  type ChartLegend,
  type ChartRow,
  type ChartSeriesInput,
  legendOption,
  numberAt,
  resolveSeries,
  seriesEntries,
  tableOf,
  tooltipBase,
  tooltipHtml,
} from "./option-parts"
import { specChart } from "./spec-chart"
import type { ChartTokens } from "./tokens"

export interface RadialStackedChartSpec {
  /** One wedge per row, laid around the circle in order. */
  data: ChartRow[]
  xKey: string
  series?: ChartSeriesInput[]
  format?: ChartFormat
  legend?: ChartLegend
}

export const radialStackedChartOption = (
  { data, xKey, ...spec }: RadialStackedChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const series = resolveSeries(tokens, data, xKey, spec.series)
  const labels = data.map((row) => String(row[xKey] ?? ""))
  const legend = legendOption(tokens, spec.legend ?? "bottom", series.length)
  const below = legend.show && legend.bottom !== undefined
  const narrow = width > 0 && width < 480

  return {
    legend: { ...legend, ...(below ? { left: "center" } : {}), data: series.map((entry) => entry.label) },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "axis",
      axisPointer: { type: "shadow" },
      formatter: (params: unknown) => {
        const index = axisParams(params)[0]?.dataIndex ?? -1
        const row = data[index]
        if (!row) return ""
        const total = series.reduce((sum, entry) => sum + (numberAt(row, entry.key) ?? 0), 0)
        return tooltipHtml(labels[index] ?? "", [
          ...series.map((entry) => ({
            name: entry.label,
            color: entry.color,
            value: format(numberAt(row, entry.key) ?? 0),
          })),
          { name: "Total", value: format(total) },
        ])
      },
    },
    polar: {
      radius: ["20%", narrow ? "70%" : "78%"],
      center: ["50%", below ? "46%" : legend.show ? "54%" : "50%"],
    },
    angleAxis: {
      type: "category",
      data: labels,
      startAngle: 90,
      axisLine: { lineStyle: { color: tokens.border } },
      axisTick: { show: false },
      axisLabel: {
        color: tokens.fgMuted,
        fontFamily: tokens.font,
        fontSize: 11,
        interval: narrow && labels.length > 8 ? 1 : 0,
      },
      splitLine: { show: true, lineStyle: { color: tokens.grid, type: "dashed" } },
    },
    radiusAxis: {
      type: "value",
      axisLine: { show: false },
      axisTick: { show: false },
      axisLabel: { show: false },
      splitNumber: 3,
      splitLine: { lineStyle: { color: tokens.grid, type: "dashed" } },
    },
    series: series.map((entry) => ({
      type: "bar",
      name: entry.label,
      coordinateSystem: "polar",
      stack: "total",
      color: entry.color,
      barCategoryGap: "12%",
      itemStyle: { borderColor: tokens.surface, borderWidth: 1 },
      emphasis: { focus: "series" },
      blur: { itemStyle: { opacity: 0.3 } },
      data: data.map((row) => numberAt(row, entry.key) ?? 0),
    })),
  } as EChartsOption
}

export interface RadialStackedChartProps extends ChartCommonProps, RadialStackedChartSpec {}

/** Stacked columns wrapped around a circle: suited to cycles such as months or hours. */
export const RadialStackedChart = specChart<RadialStackedChartSpec>({
  name: "RadialStackedChart",
  keys: ["data", "xKey", "series", "format", "legend"],
  option: radialStackedChartOption,
  table: (spec) =>
    tableOf(
      spec.data,
      spec.xKey,
      seriesEntries(spec.data, spec.xKey, spec.series),
      toFormatter(spec.format),
    ),
  isEmpty: (spec) => spec.data.length === 0,
  label: "Radial stacked chart",
  height: 380,
})

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import { tooltipBase, tooltipHtml } from "./option-parts"
import { specChart } from "./spec-chart"
import { type ChartTokens, type ChartTone, colorOf } from "./tokens"

export interface SankeyChartNode {
  /** Unique, and what links refer to. */
  name: string
  color?: ChartTone | string
}

export interface SankeyChartLink {
  source: string
  target: string
  value: number
}

export interface SankeyChartSpec {
  links: SankeyChartLink[]
  /** Order and colors. Nodes only named in `links` are added in order of appearance. */
  nodes?: SankeyChartNode[]
  format?: ChartFormat
  orient?: "horizontal" | "vertical"
}

export const sankeyNodes = ({
  links,
  nodes = [],
}: SankeyChartSpec): SankeyChartNode[] => {
  const known = new Map(nodes.map((node) => [node.name, node]))
  for (const link of links)
    for (const name of [link.source, link.target])
      if (!known.has(name)) known.set(name, { name })
  return [...known.values()]
}

export const sankeyChartOption = (
  spec: SankeyChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const nodes = sankeyNodes(spec)
  const vertical = spec.orient === "vertical"
  const narrow = width > 0 && width < 520

  return {
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const hit = params as {
          dataType: "node" | "edge"
          name: string
          value: number
          color: string
          data: { source?: string; target?: string }
        }
        return hit.dataType === "edge"
          ? tooltipHtml(`${hit.data.source ?? ""} to ${hit.data.target ?? ""}`, [
              { name: "Flow", color: hit.color, value: format(hit.value) },
            ])
          : tooltipHtml(hit.name, [{ name: "Total", value: format(hit.value) }])
      },
    },
    series: [
      {
        type: "sankey",
        orient: spec.orient ?? "horizontal",
        left: 4,
        top: 8,
        bottom: vertical ? 28 : 8,
        right: vertical ? 4 : narrow ? 84 : 120,
        nodeWidth: 10,
        nodeGap: 12,
        nodeAlign: "justify",
        draggable: false,
        emphasis: { focus: "adjacency" },
        blur: { lineStyle: { opacity: 0.08 }, itemStyle: { opacity: 0.4 } },
        lineStyle: { color: "source", opacity: 0.3, curveness: 0.5 },
        itemStyle: { borderWidth: 0, borderRadius: 2 },
        label: {
          color: tokens.fg,
          fontFamily: tokens.font,
          fontSize: 11,
          ...(vertical ? { position: "bottom" } : {}),
          formatter: (params: { name: string; value: number }) =>
            `{name|${params.name}}  {value|${format(params.value)}}`,
          rich: {
            name: { color: tokens.fg, fontFamily: tokens.font, fontSize: 11 },
            value: { color: tokens.fgFaint, fontFamily: tokens.fontMono, fontSize: 10 },
          },
        },
        data: nodes.map((node, index) => ({
          name: node.name,
          itemStyle: { color: colorOf(tokens, node.color, index) },
        })),
        links: spec.links.map((link) => ({ ...link })),
      },
    ],
  } as EChartsOption
}

export interface SankeyChartProps extends ChartCommonProps, SankeyChartSpec {}

/** Where a quantity goes: flows between stages, each band as wide as its value. */
export const SankeyChart = specChart<SankeyChartSpec>({
  name: "SankeyChart",
  keys: ["links", "nodes", "format", "orient"],
  option: sankeyChartOption,
  table: (spec) => {
    const print = toFormatter(spec.format)
    return {
      columns: ["From", "To", "Value"],
      rows: spec.links.map((link) => [link.source, link.target, print(link.value)]),
    }
  },
  isEmpty: (spec) => spec.links.length === 0,
  label: "Flow chart",
  height: 340,
})

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import {
  type ChartLegend,
  legendOption,
  legendRoom,
  tooltipBase,
  tooltipHtml,
  valueAxis,
} from "./option-parts"
import { median, specChart } from "./spec-chart"
import { type ChartTokens, type ChartTone, colorOf, withAlpha } from "./tokens"

export interface ScatterChartPoint {
  label?: string
  x: number
  y: number
  /** Sizes the bubble by area. */
  size?: number
  /** Points sharing a group share a color and a legend entry. */
  group?: string
  color?: ChartTone | string
}

export interface ScatterChartQuadrants {
  /** Where the vertical divider sits. The median of x by default. */
  x?: number
  /** Where the horizontal divider sits. The median of y by default. */
  y?: number
  /** Names for the top right, top left, bottom left and bottom right quadrants. */
  labels?: [string, string, string, string]
}

export interface ScatterChartSpec {
  data: ScatterChartPoint[]
  xLabel?: string
  yLabel?: string
  sizeLabel?: string
  xFormat?: ChartFormat
  yFormat?: ChartFormat
  sizeFormat?: ChartFormat
  /** Splits the plane into four named quadrants around two dividers. */
  quadrants?: boolean | ScatterChartQuadrants
  /** Names each point beside it. */
  labels?: boolean
  legend?: ChartLegend
}

const SIZE = { min: 8, max: 38, fixed: 11 }
const CORNERS = [
  "insideTopRight",
  "insideTopLeft",
  "insideBottomLeft",
  "insideBottomRight",
]

export const scatterChartOption = (
  {
    data,
    xLabel = "x",
    yLabel = "y",
    sizeLabel = "Size",
    quadrants,
    labels = false,
    ...spec
  }: ScatterChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const xFormat = toFormatter(spec.xFormat)
  const yFormat = toFormatter(spec.yFormat)
  const sizeFormat = toFormatter(spec.sizeFormat)
  const groups = [...new Set(data.map((point) => point.group ?? ""))]
  const legend = legendOption(tokens, spec.legend, groups.filter(Boolean).length)
  const room = legendRoom(legend)
  const sizes = data.map((point) => point.size ?? 0)
  const peak = Math.max(...sizes, 0)
  // By area, not radius, so a bubble twice the value looks twice as big.
  const radius = (size: number | undefined) =>
    peak > 0
      ? SIZE.min + (SIZE.max - SIZE.min) * Math.sqrt(Math.max(size ?? 0, 0) / peak)
      : SIZE.fixed
  const quad = quadrants
    ? {
        x:
          (typeof quadrants === "object" ? quadrants.x : undefined) ??
          median(data.map((point) => point.x)),
        y:
          (typeof quadrants === "object" ? quadrants.y : undefined) ??
          median(data.map((point) => point.y)),
        labels: typeof quadrants === "object" ? quadrants.labels : undefined,
      }
    : undefined
  const named = (title: string) => ({
    name: title,
    nameLocation: "middle" as const,
    nameTextStyle: { color: tokens.fgMuted, fontFamily: tokens.font, fontSize: 11 },
  })

  const quadrantMarks = quad
    ? {
        markLine: {
          silent: true,
          symbol: "none",
          lineStyle: { color: tokens.fgFaint, type: "dashed", width: 1 },
          label: { show: false },
          data: [{ xAxis: quad.x }, { yAxis: quad.y }],
        },
        markArea: {
          silent: true,
          // Infinity reaches the axis extent, however the axis rounds its ends.
          data: [
            [
              { xAxis: quad.x, yAxis: quad.y },
              { xAxis: Infinity, yAxis: Infinity },
            ],
            [
              { xAxis: -Infinity, yAxis: quad.y },
              { xAxis: quad.x, yAxis: Infinity },
            ],
            [
              { xAxis: -Infinity, yAxis: -Infinity },
              { xAxis: quad.x, yAxis: quad.y },
            ],
            [
              { xAxis: quad.x, yAxis: -Infinity },
              { xAxis: Infinity, yAxis: quad.y },
            ],
          ].map((area, index) => [
            {
              ...area[0],
              itemStyle: {
                color: index === 0 ? withAlpha(tokens.accent, 0.06) : "transparent",
              },
              label: {
                show: Boolean(quad.labels?.[index]),
                position: CORNERS[index],
                formatter: quad.labels?.[index] ?? "",
                color: tokens.fgFaint,
                fontFamily: tokens.font,
                fontSize: 11,
                fontWeight: 600,
                distance: 8,
              },
            },
            area[1],
          ]),
        },
      }
    : {}

  return {
    legend: { ...legend, data: groups.filter(Boolean) },
    // The grid box is the outer bound, so axis names fit inside it along with the tick labels.
    grid: {
      left: 4,
      right: 20,
      top: room.top + 4,
      bottom: room.bottom,
      outerBoundsMode: "same",
      outerBoundsContain: "all",
    },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const hit = params as { data: { index: number }; color: string }
        const point = data[hit.data.index]
        if (!point) return ""
        return tooltipHtml(point.label ?? point.group ?? "", [
          { name: xLabel, color: hit.color, value: xFormat(point.x) },
          { name: yLabel, value: yFormat(point.y) },
          ...(point.size === undefined
            ? []
            : [{ name: sizeLabel, value: sizeFormat(point.size) }]),
        ])
      },
    },
    xAxis: {
      ...valueAxis(tokens, xFormat, width),
      ...named(xLabel),
      nameGap: 28,
      scale: true,
      splitLine: { show: false },
      axisLine: { show: true, lineStyle: { color: tokens.border } },
    },
    yAxis: {
      ...valueAxis(tokens, yFormat, width),
      ...named(yLabel),
      nameGap: 40,
      scale: true,
    },
    series: groups.map((group, groupIndex) => {
      const color = colorOf(tokens, undefined, groupIndex)
      return {
        type: "scatter",
        name: group,
        color,
        data: data.flatMap((point, index) =>
          (point.group ?? "") === group
            ? [
                {
                  value: [point.x, point.y],
                  name: point.label ?? "",
                  index,
                  symbolSize: radius(point.size) * 2,
                  itemStyle: {
                    color: withAlpha(
                      point.color ? colorOf(tokens, point.color) : color,
                      peak > 0 ? 0.72 : 0.9,
                    ),
                    borderColor: tokens.surface,
                    borderWidth: 1,
                  },
                },
              ]
            : [],
        ),
        label: {
          show: labels,
          position: "right",
          distance: 6,
          color: tokens.fgMuted,
          fontFamily: tokens.font,
          fontSize: 10,
          formatter: (params: { name: string }) => params.name,
        },
        labelLayout: { hideOverlap: true },
        emphasis: { focus: "self", scale: 1.15 },
        blur: { itemStyle: { opacity: 0.3 } },
        ...(groupIndex === 0 ? quadrantMarks : {}),
      }
    }),
  } as EChartsOption
}

export interface ScatterChartProps extends ChartCommonProps, ScatterChartSpec {}

/** Two measures per point, optionally sized by a third and split into quadrants. */
export const ScatterChart = specChart<ScatterChartSpec>({
  name: "ScatterChart",
  keys: [
    "data",
    "xLabel",
    "yLabel",
    "sizeLabel",
    "xFormat",
    "yFormat",
    "sizeFormat",
    "quadrants",
    "labels",
    "legend",
  ],
  option: scatterChartOption,
  table: (spec) => {
    const x = toFormatter(spec.xFormat)
    const y = toFormatter(spec.yFormat)
    const size = toFormatter(spec.sizeFormat)
    const sized = spec.data.some((point) => point.size !== undefined)
    return {
      columns: [
        "Label",
        spec.xLabel ?? "x",
        spec.yLabel ?? "y",
        ...(sized ? [spec.sizeLabel ?? "Size"] : []),
      ],
      rows: spec.data.map((point) => [
        point.label ?? point.group ?? "",
        x(point.x),
        y(point.y),
        ...(sized ? [point.size === undefined ? null : size(point.size)] : []),
      ]),
    }
  },
  isEmpty: (spec) => spec.data.length === 0,
  label: "Scatter chart",
  height: 360,
})

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, formatPercent, toFormatter } from "./format"
import { tooltipBase, tooltipHtml } from "./option-parts"
import { specChart } from "./spec-chart"
import { type ChartTokens, withAlpha } from "./tokens"

export interface SlopeChartRow {
  label: string
  from: number
  to: number
}

export interface SlopeChartSpec {
  data: SlopeChartRow[]
  fromLabel?: string
  toLabel?: string
  format?: ChartFormat
  /** For measures where a fall is good, such as cost or churn. */
  invert?: boolean
  /** Rows to draw in full color; the rest recede. Every row is colored when omitted. */
  highlight?: string[]
}

const change = (row: SlopeChartRow) =>
  row.from === 0 ? 0 : (row.to - row.from) / Math.abs(row.from)

export const slopeChartOption = (
  {
    data,
    fromLabel = "Before",
    toLabel = "After",
    invert = false,
    highlight,
    ...spec
  }: SlopeChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const narrow = width > 0 && width < 480
  const values = data.flatMap((row) => [row.from, row.to])
  const low = Math.min(...values)
  const high = Math.max(...values)
  const pad = (high - low || 1) * 0.06
  const side = narrow ? 92 : 140

  return {
    grid: { left: side, right: side, top: 36, bottom: 8 },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const row = data[(params as { seriesIndex: number }).seriesIndex]
        if (!row) return ""
        const delta = change(row)
        return tooltipHtml(row.label, [
          { name: fromLabel, value: format(row.from) },
          { name: toLabel, value: format(row.to) },
          { name: "Change", value: `${delta > 0 ? "+" : ""}${formatPercent(delta)}` },
        ])
      },
    },
    xAxis: {
      type: "category",
      data: [fromLabel, toLabel],
      position: "top",
      boundaryGap: false,
      axisTick: { show: false },
      axisLine: { show: false },
      axisLabel: {
        color: tokens.fgMuted,
        fontFamily: tokens.font,
        fontSize: 11,
        fontWeight: 600,
        margin: 14,
      },
      splitLine: { show: true, lineStyle: { color: tokens.border } },
    },
    yAxis: { type: "value", show: false, min: low - pad, max: high + pad },
    series: data.map((row) => {
      const rising = row.to >= row.from !== invert
      const lit = !highlight || highlight.includes(row.label)
      const tone = rising ? tokens.success : tokens.danger
      const color = lit ? tone : withAlpha(tokens.fgFaint, 0.5)
      const text = {
        fontFamily: tokens.font,
        fontSize: 11,
        color: lit ? tokens.fg : tokens.fgFaint,
      }
      return {
        type: "line",
        name: row.label,
        symbol: "circle",
        symbolSize: 7,
        z: lit ? 3 : 2,
        lineStyle: { color, width: lit ? 2 : 1.5 },
        itemStyle: { color, borderColor: tokens.surface, borderWidth: 1.5 },
        emphasis: { focus: "series", lineStyle: { width: 3 } },
        blur: { lineStyle: { opacity: 0.15 }, itemStyle: { opacity: 0.15 } },
        labelLayout: { hideOverlap: true },
        data: [
          {
            value: row.from,
            label: {
              show: true,
              ...text,
              position: "left",
              distance: 8,
              formatter: `${row.label}  ${format(row.from)}`,
            },
          },
          {
            value: row.to,
            label: {
              show: true,
              ...text,
              position: "right",
              distance: 8,
              formatter: narrow ? format(row.to) : `${format(row.to)}  ${row.label}`,
            },
          },
        ],
      }
    }),
  } as EChartsOption
}

export interface SlopeChartProps extends ChartCommonProps, SlopeChartSpec {}

/** Who rose and who fell between two moments, and by how much, one line per row. */
export const SlopeChart = specChart<SlopeChartSpec>({
  name: "SlopeChart",
  keys: ["data", "fromLabel", "toLabel", "format", "invert", "highlight"],
  option: slopeChartOption,
  table: (spec) => {
    const print = toFormatter(spec.format)
    return {
      columns: ["Label", spec.fromLabel ?? "Before", spec.toLabel ?? "After", "Change"],
      rows: spec.data.map((row) => {
        const delta = change(row)
        return [
          row.label,
          print(row.from),
          print(row.to),
          `${delta > 0 ? "+" : ""}${formatPercent(delta)}`,
        ]
      }),
    }
  },
  isEmpty: (spec) => spec.data.length === 0,
  label: "Slope chart",
  height: 360,
})

