import {
  type ForwardRefExoticComponent,
  forwardRef,
  type RefAttributes,
  useCallback,
  useMemo,
} from "react"
import {
  Chart,
  type ChartCommonProps,
  type ChartSummary,
  useStableSpec,
} from "./chart"
import type { EChartsOption } from "./echarts"
import type { ChartTokens } from "./tokens"

export interface SpecChartConfig<S extends object> {
  name: string
  /** Every spec prop; anything else is spread onto the root element. */
  keys: readonly (keyof S & string)[]
  option: (spec: S, tokens: ChartTokens, width: number) => EChartsOption
  table: (spec: S) => ChartSummary
  isEmpty: (spec: S) => boolean
  label: string
  height?: number | ((spec: S) => number)
}

export type SpecChartComponent<S extends object> = ForwardRefExoticComponent<
  ChartCommonProps & S & RefAttributes<HTMLDivElement>
>

/**
 * One data-first chart from its pure option builder: splits spec props from DOM props, keeps
 * the spec stable across equal re-renders, and adds the hidden table and the empty note.
 */
export const specChart = <S extends object>(
  config: SpecChartConfig<S>,
): SpecChartComponent<S> => {
  const Component = forwardRef<HTMLDivElement, ChartCommonProps & S>((props, ref) => {
    const {
      label = config.label,
      height,
      summary = true,
      empty = "No data to plot",
      ...rest
    } = props as ChartCommonProps & Record<string, unknown>
    const picked: Record<string, unknown> = {}
    const dom: Record<string, unknown> = {}
    for (const [key, value] of Object.entries(rest)) {
      if ((config.keys as readonly string[]).includes(key)) picked[key] = value
      else dom[key] = value
    }
    // Fixed length, so the memo's dependency list never changes size between renders.
    const functions = config.keys.map((key) =>
      typeof picked[key] === "function" ? picked[key] : undefined,
    )
    const spec = useStableSpec(picked as S, ...functions)
    const option = useCallback(
      (tokens: ChartTokens, width: number) => config.option(spec, tokens, width),
      [spec],
    )
    const table = useMemo(
      () => (summary ? config.table(spec) : undefined),
      [summary, spec],
    )
    const isEmpty = config.isEmpty(spec)
    const fitted =
      height ??
      (typeof config.height === "function" ? config.height(spec) : config.height)
    return (
      <Chart
        ref={ref}
        option={option}
        label={label}
        height={fitted}
        summary={isEmpty ? undefined : table}
        empty={isEmpty ? empty : undefined}
        {...dom}
      />
    )
  })
  Component.displayName = config.name
  return Component as SpecChartComponent<S>
}

/** `+12`, `-4`: direction in the text, so it never rests on color alone. */
export const signedFormat =
  (format: (value: number) => string) =>
  (value: number): string =>
    `${value > 0 ? "+" : ""}${format(value)}`

/** The minimal slice of the ECharts custom-series API these charts draw with. */
export interface CustomApi {
  coord: (point: number[]) => number[]
  size: (span: number[]) => number[]
}

export interface CustomParams {
  dataIndex: number
  coordSys: { x: number; y: number; width: number; height: number }
}

export const median = (values: readonly number[]): number => {
  const sorted = [...values].sort((a, b) => a - b)
  const middle = Math.floor(sorted.length / 2)
  if (sorted.length === 0) return 0
  return sorted.length % 2
    ? (sorted[middle] ?? 0)
    : ((sorted[middle - 1] ?? 0) + (sorted[middle] ?? 0)) / 2
}

const channelsOf = (color: string): number[] | null => {
  const value = color.trim()
  const hex = /^#([0-9a-f]{6})$/i.exec(value)?.[1]
  if (hex)
    return [0, 2, 4].map((at) => Number.parseInt(hex.slice(at, at + 2), 16)).concat(1)
  const parts = /^rgba?\(([^)]+)\)$/i
    .exec(value)?.[1]
    ?.split(/[\s,/]+/)
    .filter(Boolean)
    .map(Number)
  if (!parts || parts.length < 3 || parts.some(Number.isNaN)) return null
  return [parts[0] ?? 0, parts[1] ?? 0, parts[2] ?? 0, parts[3] ?? 1]
}

const luminance = ([r = 0, g = 0, b = 0]: number[]): number => {
  const linear = (value: number) => {
    const c = value / 255
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4
  }
  return 0.2126 * linear(r) + 0.7152 * linear(g) + 0.0722 * linear(b)
}

/** The theme's ink or its surface, whichever reads better on `fill` laid over the surface. */
export const inkOn = (tokens: ChartTokens, fill: string): string => {
  const top = channelsOf(fill)
  const paper = channelsOf(tokens.surface)
  const ink = channelsOf(tokens.fg)
  if (!top || !paper || !ink) return tokens.fg
  const alpha = top[3] ?? 1
  const ground = luminance(
    top.slice(0, 3).map((c, i) => c * alpha + (paper[i] ?? 0) * (1 - alpha)),
  )
  const contrast = (other: number) =>
    (Math.max(other, ground) + 0.05) / (Math.min(other, ground) + 0.05)
  return contrast(luminance(ink)) >= contrast(luminance(paper))
    ? tokens.fg
    : tokens.surface
}

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, formatPercent, toFormatter } from "./format"
import {
  axisParams,
  type ChartLegend,
  type ChartRow,
  type ChartSeriesInput,
  categoryAxis,
  legendOption,
  legendRoom,
  numberAt,
  resolveSeries,
  seriesEntries,
  tooltipBase,
  tooltipHtml,
  valueAxis,
} from "./option-parts"
import { inkOn, specChart } from "./spec-chart"
import { type ChartTokens, withAlpha } from "./tokens"

export interface StackedPercentBarSpec {
  data: ChartRow[]
  xKey: string
  series?: ChartSeriesInput[]
  /** How raw values print in the tooltip next to their share. */
  format?: ChartFormat
  orientation?: "horizontal" | "vertical"
  /** Prints each segment's share inside it when it is wide enough. On by default. */
  labels?: boolean
  legend?: ChartLegend
}

/** Each row's series as shares of that row's total, 0 to 1. */
export const percentRows = (
  data: readonly ChartRow[],
  keys: readonly string[],
): number[][] =>
  data.map((row) => {
    const values = keys.map((key) => Math.max(numberAt(row, key) ?? 0, 0))
    const total = values.reduce((sum, value) => sum + value, 0)
    return values.map((value) => (total > 0 ? value / total : 0))
  })

export const stackedPercentBarOption = (
  {
    data,
    xKey,
    orientation = "horizontal",
    labels = true,
    ...spec
  }: StackedPercentBarSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const series = resolveSeries(tokens, data, xKey, spec.series)
  const shares = percentRows(
    data,
    series.map((entry) => entry.key),
  )
  const legend = legendOption(tokens, spec.legend ?? "top", series.length)
  const sideways = orientation === "horizontal"
  const names = data.map((row) => String(row[xKey] ?? ""))
  const category = {
    ...categoryAxis(tokens, names),
    ...(sideways ? { inverse: true, axisLine: { show: false } } : {}),
  }
  const value = {
    ...valueAxis(tokens, (share) => formatPercent(share, 0), width),
    min: 0,
    max: 1,
    interval: 0.25,
  }

  return {
    legend: { ...legend, data: series.map((entry) => entry.label) },
    grid: { left: 4, right: 16, ...legendRoom(legend), containLabel: true },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "axis",
      axisPointer: {
        type: "shadow",
        shadowStyle: { color: withAlpha(tokens.fgFaint, 0.08) },
      },
      formatter: (params: unknown) => {
        const index = axisParams(params)[0]?.dataIndex ?? -1
        const row = data[index]
        if (!row) return ""
        return tooltipHtml(
          names[index] ?? "",
          series.map((entry, at) => {
            const raw = numberAt(row, entry.key)
            return {
              name: entry.label,
              color: entry.color,
              value: `${formatPercent(shares[index]?.[at] ?? 0)}${raw === null ? "" : `  ${format(raw)}`}`,
            }
          }),
        )
      },
    },
    xAxis: sideways ? value : category,
    yAxis: sideways ? category : value,
    series: series.map((entry, at) => ({
      type: "bar",
      name: entry.label,
      stack: "share",
      barMaxWidth: 28,
      color: entry.color,
      emphasis: { focus: "series" },
      blur: { itemStyle: { opacity: 0.3 } },
      itemStyle: { borderColor: tokens.surface, borderWidth: 1 },
      label: {
        show: labels,
        color: inkOn(tokens, entry.color),
        fontFamily: tokens.fontMono,
        fontSize: 10,
        formatter: (params: { value: number }) =>
          params.value >= 0.08 ? formatPercent(params.value, 0) : "",
      },
      data: shares.map((row) => row[at] ?? 0),
    })),
  } as EChartsOption
}

export interface StackedPercentBarProps extends ChartCommonProps, StackedPercentBarSpec {}

/** Composition across rows: every bar runs to 100%, so mix compares where totals differ. */
export const StackedPercentBar = specChart<StackedPercentBarSpec>({
  name: "StackedPercentBar",
  keys: ["data", "xKey", "series", "format", "orientation", "labels", "legend"],
  option: stackedPercentBarOption,
  table: (spec) => {
    const entries = seriesEntries(spec.data, spec.xKey, spec.series)
    const shares = percentRows(
      spec.data,
      entries.map((entry) => entry.key),
    )
    return {
      columns: [spec.xKey, ...entries.map((entry) => entry.label ?? entry.key)],
      rows: spec.data.map((row, index) => [
        String(row[spec.xKey] ?? ""),
        ...entries.map((_, at) => formatPercent(shares[index]?.[at] ?? 0)),
      ]),
    }
  },
  isEmpty: (spec) => spec.data.length === 0,
  label: "100% stacked bar chart",
  height: (spec) =>
    spec.orientation === "vertical" ? 300 : Math.max(spec.data.length * 40 + 60, 160),
})

"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import {
  type ChartLegend,
  type ChartRow,
  type ChartSeriesInput,
  legendOption,
  numberAt,
  resolveSeries,
  seriesEntries,
  tableOf,
  tooltipBase,
  tooltipHtml,
} from "./option-parts"
import { specChart } from "./spec-chart"
import type { ChartTokens } from "./tokens"

export interface ThemeRiverChartSpec {
  /** One row per moment. `xKey` holds an ISO date, a timestamp, or a plain number. */
  data: ChartRow[]
  xKey: string
  series?: ChartSeriesInput[]
  format?: ChartFormat
  legend?: ChartLegend
}

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]

const isTime = (data: readonly ChartRow[], xKey: string) =>
  typeof data[0]?.[xKey] === "string"

const dateLabel = (value: number) => {
  const date = new Date(value)
  return `${MONTHS[date.getUTCMonth()] ?? ""} ${date.getUTCDate()}`
}

export const themeRiverChartOption = (
  { data, xKey, ...spec }: ThemeRiverChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const series = resolveSeries(tokens, data, xKey, spec.series)
  const legend = legendOption(tokens, spec.legend, series.length)
  const time = isTime(data, xKey)
  const below = legend.show && legend.bottom !== undefined
  const stamp = (row: ChartRow) => {
    const raw = row[xKey]
    return time ? Date.parse(String(raw)) : Number(raw)
  }
  const tickText = (value: number) => (time ? dateLabel(value) : format(value))
  const most = width > 0 && width < 420 ? 3 : 6
  // A time axis adds its own month-boundary ticks that crowd the weekly ones, so labels sit on
  // evenly spaced data points instead.
  const stamps = time ? data.map(stamp).filter(Number.isFinite) : []
  const every = Math.max(1, Math.ceil(stamps.length / most))
  const ticks = stamps.filter((_, index) => index % every === 0)

  return {
    color: series.map((entry) => entry.color),
    legend: { ...legend, data: series.map((entry) => entry.label) },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "axis",
      axisPointer: { type: "line", lineStyle: { color: tokens.border } },
      formatter: (params: unknown) => {
        const hits = Array.isArray(params) ? (params as { value: unknown[] }[]) : []
        const at = Number(hits[0]?.value?.[0])
        const row = data.find((entry) => stamp(entry) === at) ?? data[0]
        if (!row) return ""
        return tooltipHtml(
          time ? String(row[xKey] ?? "") : tickText(at),
          series.map((entry) => ({
            name: entry.label,
            color: entry.color,
            value: format(numberAt(row, entry.key) ?? 0),
          })),
        )
      },
    },
    singleAxis: {
      type: time ? "time" : "value",
      top: legend.show && !below ? 40 : 12,
      bottom: below ? 52 : 28,
      left: 8,
      right: 8,
      min: "dataMin",
      max: "dataMax",
      splitNumber: most,
