"use client"

import type { ChartCommonProps } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, formatPercent, toFormatter } from "./format"
import {
  type ChartDatum,
  legendOption,
  tooltipBase,
  tooltipHtml,
} from "./option-parts"
import { specChart } from "./spec-chart"
import { type ChartTokens, colorOf, withAlpha } from "./tokens"

export interface WaffleChartSpec {
  data: ChartDatum[]
  format?: ChartFormat
  /** Cells per row. */
  columns?: number
  /** Rows of cells; `columns × rows` cells stand for the whole. */
  rows?: number
  /** Rounded cells, from square (0) to dots (1). */
  roundness?: number
  /** Counts toward the whole beyond the data; the leftover cells stay empty. */
  total?: number
}

interface WaffleApi {
  value: (dimension: number) => number
  getWidth: () => number
  getHeight: () => number
}

/** Cells per datum by largest remainder, so the counts always add up to the grid. */
export const waffleCells = (
  data: readonly ChartDatum[],
  cells: number,
  total?: number,
): number[] => {
  const sum = data.reduce((acc, datum) => acc + Math.max(datum.value, 0), 0)
  const whole = Math.max(total ?? sum, sum)
  if (whole <= 0) return data.map(() => 0)
  const exact = data.map((datum) => (Math.max(datum.value, 0) / whole) * cells)
  const counts = exact.map(Math.floor)
  const target = Math.round((sum / whole) * cells)
  let left = target - counts.reduce((acc, count) => acc + count, 0)
  const order = exact
    .map((value, index) => ({ index, rest: value - Math.floor(value) }))
    .sort((a, b) => b.rest - a.rest)
  for (const { index } of order) {
    if (left <= 0) break
    counts[index] = (counts[index] ?? 0) + 1
    left -= 1
  }
  return counts
}

export const waffleChartOption = (
  { data, columns = 10, rows = 10, roundness = 0.3, total, ...spec }: WaffleChartSpec,
  tokens: ChartTokens,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const cells = columns * rows
  const counts = waffleCells(data, cells, total)
  const sum = Math.max(
    total ?? 0,
    data.reduce((acc, datum) => acc + Math.max(datum.value, 0), 0),
  )
  const colors = data.map((datum, index) => colorOf(tokens, datum.color, index))
  const legend = legendOption(tokens, "bottom", data.length)
  const starts = counts.map((_, index) =>
    counts.slice(0, index).reduce((acc, count) => acc + count, 0),
  )
  const filled = counts.reduce((acc, count) => acc + count, 0)

  const cell = (index: number, api: WaffleApi, fill: string) => {
    const room = 72
    const width = api.getWidth()
    const height = api.getHeight() - room
    const gap = 3
    const side = Math.max(
      Math.min((width - gap * (columns - 1)) / columns, (height - gap * (rows - 1)) / rows),
      2,
    )
    const gridWidth = side * columns + gap * (columns - 1)
    const left = (width - gridWidth) / 2
    const column = index % columns
    const row = Math.floor(index / columns)
    return {
      type: "rect",
      shape: {
        x: left + column * (side + gap),
        y: 4 + row * (side + gap),
        width: side,
        height: side,
        r: (side / 2) * Math.min(Math.max(roundness, 0), 1),
      },
      style: { fill },
    }
  }

  const share = (index: number) => (sum > 0 ? (data[index]?.value ?? 0) / sum : 0)

  return {
    legend: {
      ...legend,
      // Plain wraps onto a second line; a scrolling legend would hide the last share.
      type: "plain",
      left: "center",
      icon: "roundRect",
      data: data.map((datum) => datum.label),
      formatter: (name: string) => {
        const index = data.findIndex((datum) => datum.label === name)
        return `${name}  ${formatPercent(share(index), 0)}`
      },
    },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const index = (params as { seriesIndex: number }).seriesIndex
        const datum = data[index]
        return datum
          ? tooltipHtml(datum.label, [
              { name: "Value", color: colors[index], value: format(datum.value) },
              { name: "Share", value: formatPercent(share(index)) },
            ])
          : ""
      },
    },
    series: [
      ...data.map((datum, index) => ({
        type: "custom",
        name: datum.label,
        coordinateSystem: "none",
        color: colors[index],
        emphasis: { focus: "series" },
        blur: { itemStyle: { opacity: 0.25 } },
        data: Array.from({ length: counts[index] ?? 0 }, (_, at) => (starts[index] ?? 0) + at),
        renderItem: (_params: unknown, api: WaffleApi) =>
          cell(api.value(0), api, colors[index] ?? tokens.accent),
      })),
      {
        type: "custom",
        name: "Remaining",
        coordinateSystem: "none",
        silent: true,
        tooltip: { show: false },
        data: Array.from({ length: cells - filled }, (_, at) => filled + at),
        renderItem: (_params: unknown, api: WaffleApi) =>
          cell(api.value(0), api, withAlpha(tokens.fgFaint, 0.14)),
      },
    ],
  } as EChartsOption
}

export interface WaffleChartProps extends ChartCommonProps, WaffleChartSpec {}

/** Parts of a whole as a grid of cells, each one a fixed share: easier to count than a pie. */
export const WaffleChart = specChart<WaffleChartSpec>({
  name: "WaffleChart",
  keys: ["data", "format", "columns", "rows", "roundness", "total"],
  option: (spec, tokens) => waffleChartOption(spec, tokens),
  table: (spec) => {
    const print = toFormatter(spec.format)
    const sum = Math.max(
      spec.total ?? 0,
      spec.data.reduce((acc, datum) => acc + Math.max(datum.value, 0), 0),
    )
    return {
      columns: ["Label", "Value", "Share"],
      rows: spec.data.map((datum) => [
        datum.label,
        print(datum.value),
        formatPercent(sum > 0 ? datum.value / sum : 0),
      ]),
    }
  },
  isEmpty: (spec) => spec.data.length === 0,
  label: "Waffle chart",
  height: 320,
})

"use client"

import type { ChartCommonProps, ChartSummary } from "./chart"
import type { EChartsOption } from "./echarts"
import { type ChartFormat, toFormatter } from "./format"
import { categoryAxis, tooltipBase, tooltipHtml, valueAxis } from "./option-parts"
import {
  type CustomApi,
  type CustomParams,
  signedFormat,
  specChart,
} from "./spec-chart"
import { type ChartTokens, withAlpha } from "./tokens"

/** `total` is a level, not a change: the start, a subtotal or the end. */
export type WaterfallChartKind = "delta" | "total"

export interface WaterfallChartStep {
  label: string
  /** A change for a delta. For a total, the level; omitted, the running sum so far. */
  value?: number
  kind?: WaterfallChartKind
}

export interface WaterfallChartSpec {
  data: WaterfallChartStep[]
  format?: ChartFormat
  /** For measures where a fall is good, such as cost. */
  invert?: boolean
  /** Prints each change above its bar. */
  values?: boolean
}

export interface WaterfallChartBar {
  label: string
  kind: WaterfallChartKind
  /** The signed change, or the level for a total. */
  value: number
  low: number
  high: number
  /** The running level after this step. */
  level: number
}

/** Where each bar floats: deltas hang off the running sum, totals stand on zero. */
export const waterfallBars = (
  steps: readonly WaterfallChartStep[],
): WaterfallChartBar[] => {
  let running = 0
  return steps.map((step) => {
    const kind = step.kind ?? "delta"
    if (kind === "total") {
      running = step.value ?? running
      return {
        label: step.label,
        kind,
        value: running,
        low: Math.min(0, running),
        high: Math.max(0, running),
        level: running,
      }
    }
    const change = step.value ?? 0
    const before = running
    running += change
    return {
      label: step.label,
      kind,
      value: change,
      low: Math.min(before, running),
      high: Math.max(before, running),
      level: running,
    }
  })
}

export const waterfallChartOption = (
  { data, invert = false, values = true, ...spec }: WaterfallChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const signed = signedFormat(format)
  const bars = waterfallBars(data)
  const last = bars.length - 1
  const slot = width > 0 ? width / Math.max(bars.length, 1) : 96
  const cramped = slot < 56
  const colorOf = (bar: WaterfallChartBar, index: number) =>
    bar.kind === "total"
      ? index === last
        ? tokens.accent
        : (tokens.palette[1] ?? tokens.fgMuted)
      : bar.value >= 0 !== invert
        ? tokens.success
        : tokens.danger
  const caption = (bar: WaterfallChartBar) =>
    bar.kind === "total" ? format(bar.value) : signed(bar.value)

  return {
    grid: { left: 4, right: 8, top: values ? 28 : 12, bottom: 4, containLabel: true },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const bar = bars[(params as { dataIndex: number }).dataIndex]
        if (!bar) return ""
        return tooltipHtml(
          bar.label,
          bar.kind === "total"
            ? [{ name: "Level", value: format(bar.level) }]
            : [
                { name: "Change", color: colorOf(bar, -1), value: signed(bar.value) },
                { name: "Level after", value: format(bar.level) },
              ],
        )
      },
    },
    xAxis: {
      ...categoryAxis(
        tokens,
        bars.map((bar) => bar.label),
      ),
      axisLabel: {
        ...categoryAxis(tokens, []).axisLabel,
        interval: 0,
        hideOverlap: false,
        rotate: cramped ? 40 : 0,
        width: cramped ? 72 : Math.max(slot - 8, 44),
        overflow: "truncate",
      },
    },
    yAxis: valueAxis(tokens, format, width),
    series: [
      {
        type: "custom",
        name: "Steps",
        encode: { x: 0, y: [1, 2] },
        data: bars.map((bar, index) => [index, bar.low, bar.high]),
        animationDelay: (index: number) => index * 40,
        renderItem: (params: CustomParams, api: CustomApi) => {
          const index = params.dataIndex
          const bar = bars[index]
          if (!bar) return null
          const band = api.size([1, 0])[0] ?? 0
          const thick = Math.min(44, band * 0.62)
          const [x = 0, bottom = 0] = api.coord([index, bar.low])
          const top = api.coord([index, bar.high])[1] ?? 0
          const left = x - thick / 2
          const fill = colorOf(bar, index)
          const before = bars[index - 1]
          const children: unknown[] = [
            {
              type: "rect",
              shape: {
                x: left,
                y: top,
                width: thick,
                height: Math.max(bottom - top, 1),
                r: 3,
              },
              style: { fill },
              emphasis: { style: { fill: withAlpha(fill, 0.82) } },
            },
          ]
          if (before) {
            const y = api.coord([index, before.level])[1] ?? 0
            children.push({
              type: "line",
              silent: true,
              shape: { x1: left - (band - thick), y1: y, x2: left, y2: y },
              style: { stroke: tokens.fgFaint, lineWidth: 1, lineDash: [3, 3] },
            })
          }
          if (values && !(cramped && bar.kind === "delta"))
            children.push({
              type: "text",
              silent: true,
              x,
              y: top - 6,
              style: {
                text: caption(bar),
                fill: tokens.fgMuted,
                font: `600 11px ${tokens.fontMono}`,
                align: "center",
                verticalAlign: "bottom",
              },
            })
          return { type: "group", children }
        },
      },
    ],
  } as EChartsOption
}

export const waterfallChartTable = ({
  data,
  format,
}: WaterfallChartSpec): ChartSummary => {
  const print = toFormatter(format)
  return {
    columns: ["Step", "Change", "Level"],
    rows: waterfallBars(data).map((bar) => [
      bar.label,
      bar.kind === "total" ? null : signedFormat(print)(bar.value),
      print(bar.level),
    ]),
  }
}

export interface WaterfallChartProps extends ChartCommonProps, WaterfallChartSpec {}

/** A bridge from a start to an end: each change floats on the running sum. */
export const WaterfallChart = specChart<WaterfallChartSpec>({
  name: "WaterfallChart",
  keys: ["data", "format", "invert", "values"],
  option: waterfallChartOption,
  table: waterfallChartTable,
  isEmpty: (spec) => spec.data.length === 0,
  label: "Waterfall chart",
  height: 320,
})
